pub fn extract_hoist(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
    ordinal: u32,
) -> Result<Snapshot> {
    move_def(store, langs, snap, id, new_parent, Some(ordinal))
}

/// Parse the destination file so inherited generics / outer locals match the
/// new parent, then copy the subtree's content and bytes back. Reorder under
/// the same parent does not call this — the env did not change.
fn reresolve_subtree(
    store: &dyn Store,
    langs: &Langs,
    snap: &mut Snapshot,
    id: EntityId,
) -> Result<()> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let rendered = render(snap, store, langs, false)?;
    let src = rendered
        .files
        .get(&rec.file)
        .ok_or_else(|| Error::Other(format!("re-resolve missing file {}", rec.file)))?;
    let env = env_from_snapshot(snap);
    let part = ingest_file_prev(
        src,
        rec.file.clone(),
        lang,
        store,
        snap.change,
        Some(snap),
        &env,
    )?;
    for eid in subtree(snap, id) {
        let (name, kind, parent) = {
            let rec = snap.entities.get(&eid).ok_or(Error::NoSuchEntity(eid))?;
            (rec.name.clone(), rec.kind, rec.parent)
        };
        let fresh = part
            .entities
            .get(&eid)
            .or_else(|| {
                part.entities
                    .values()
                    .find(|r| r.name == name && r.kind == kind && r.parent == parent)
            })
            .ok_or_else(|| Error::Other(format!("re-resolve lost {name}")))?;
        let content = fresh.content;
        let bytes = fresh.bytes;
        if let Some(dest) = snap.entities.get_mut(&eid) {
            dest.content = content;
            dest.bytes = bytes;
        }
    }
    Ok(())
}

pub fn delete(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Snapshot> {
    let tree = subtree(snap, id);
    let mut outside = Vec::new();
    for d in &tree {
        outside.extend(
            referrers(snap, store, *d)?
                .into_iter()
                .filter(|r| !tree.contains(r)),
        );
    }
    outside.sort();
    outside.dedup();
    if !outside.is_empty() {
        let named: Vec<String> = outside
            .iter()
            .take(5)
            .map(|r| match snap.entities.get(r) {
                Some(rec) => format!("{} ({}⟨{}⟩)", rec.name, rec.file, r.short()),
                None => format!("⟨{}⟩", r.short()),
            })
            .collect();
        let more = if outside.len() > 5 {
            format!(", and {} more", outside.len() - 5)
        } else {
            String::new()
        };
        return Err(Error::Other(format!(
            "delete refused: still referenced by {}{more}",
            named.join(", ")
        )));
    }
    let parent = snap.entities.get(&id).and_then(|r| r.parent);
    let mut next = snap.clone();
    for d in tree {
        next.entities.remove(&d);
    }
    if let Some(p) = parent {
        if next.entities.contains_key(&p) {
            let mut kids = child_ids_of(store, snap, p)?;
            kids.retain(|c| *c != id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
    }
    Ok(next)
}

pub fn inline(store: &dyn Store, langs: &Langs, snap: &Snapshot, id: EntityId) -> Result<Snapshot> {
    snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let sites = name_use_sites(snap, store, id)?;
    if sites.len() != 1 {
        return Err(Error::Other(format!(
            "inline requires a single use; found {}",
            sites.len()
        )));
    }
    let referrer = sites[0];
    if subtree(snap, referrer).contains(&id) {
        return Err(Error::Other(
            "inline cannot target an item still nested in the call site; extract first".into(),
        ));
    }
    let replacement = inlined_call_text(store, langs, snap, id, referrer)?;
    let (next, _) = edit_def(store, langs, snap, referrer, &replacement)?;
    delete(&next, store, id)
}

/// `Chunk::Name(id)` sites, including recursive uses inside `id` itself.
/// The declaration hole is `Name(SELF)`, not `Name(id)`.
fn name_use_sites(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Vec<EntityId>> {
    let mut sites = Vec::new();
    for (oid, rec) in &snap.entities {
        let n = store
            .get_bytes_blob(rec.bytes)?
            .chunks()
            .iter()
            .filter(|c| matches!(c, Chunk::Name(e) if *e == id))
            .count();
        for _ in 0..n {
            sites.push(*oid);
        }
    }
    Ok(sites)
}

fn inlined_call_text(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    referrer: EntityId,
) -> Result<Vec<u8>> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let (callee, _) = render_entity(snap, store, id, false)?;
    let (params, body) = callee_params_and_body(lang, &callee)?;
    let (caller, map) = render_entity(snap, store, referrer, true)?;
    let ranges: Vec<ByteRange> = map
        .as_deref()
        .unwrap_or(&[])
        .iter()
        .filter_map(|(r, ident)| match ident {
            IdentRef::Entity(e) if *e == id => Some(*r),
            _ => None,
        })
        .collect();
    match ranges.as_slice() {
        [range] => {
            let name_end = range.end as usize;
            if name_end > caller.len() || (range.start as usize) > name_end {
                return Err(Error::Other("inline call range is out of bounds".into()));
            }
            let (call_end, args) = extend_call(&caller, name_end)?;
            if args.len() != params.len() {
                return Err(Error::Other(format!(
                    "inline expected {} argument(s), found {}",
                    params.len(),
                    args.len()
                )));
            }
            let mut block = bind_and_body(&params, &args, &body);
            if rust_postfix(&caller, call_end) {
                if lang.name() != "rust" {
                    return Err(Error::Other(
                        "inline of an expression-position call is only supported in rust".into(),
                    ));
                }
                block = format!("({block})");
            }
            let start = range.start as usize;
            let mut out = Vec::with_capacity(caller.len() + block.len());
            out.extend_from_slice(&caller[..start]);
            out.extend_from_slice(block.as_bytes());
            out.extend_from_slice(&caller[call_end..]);
            Ok(out)
        }
        _ => Err(Error::Other(format!(
            "inline needs one call name in the unique user; found {}",
            ranges.len()
        ))),
    }
}

fn callee_params_and_body(lang: &dyn Lang, src: &[u8]) -> Result<(Vec<String>, String)> {
    let tree = parse(src, lang)?;
    let item = entity_item_node(tree.root_node(), lang)
        .ok_or_else(|| Error::Other("inline target does not parse as a language item".into()))?;
    let rule = lang
        .entity_kinds()
        .iter()
        .find(|r| r.node_kind == item.kind())
        .ok_or_else(|| Error::Other("inline target is not a language item".into()))?;
    let body_field = rule.body_field.ok_or_else(|| {
        Error::Other("inline needs an item with a body (not a type or signature)".into())
    })?;
    let body = item
        .child_by_field_name(body_field)
        .ok_or_else(|| Error::Other("inline target has no body".into()))?;
    let params = match item.child_by_field_name("parameters") {
        Some(n) => param_names(n, src)?,
        None => Vec::new(),
    };
    Ok((params, node_src(src, body)))
}

fn entity_item_node<'a>(
    node: tree_sitter::Node<'a>,
    lang: &dyn Lang,
) -> Option<tree_sitter::Node<'a>> {
    if lang
        .entity_kinds()
        .iter()
        .any(|r| r.node_kind == node.kind())
    {
        return Some(node);
    }
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        if let Some(hit) = entity_item_node(ch, lang) {
            return Some(hit);
        }
    }
    None
}

fn param_names(params: tree_sitter::Node<'_>, src: &[u8]) -> Result<Vec<String>> {
    let mut names = Vec::new();
    let mut c = params.walk();
    for ch in params.named_children(&mut c) {
        match ch.kind() {
            "self_parameter" => {
                return Err(Error::Other(
                    "inline of a method (self) is not supported".into(),
                ));
            }
            "identifier" => names.push(node_src(src, ch)),
            "parameter" | "required_parameter" | "optional_parameter" | "rest_parameter"
            | "assignment_pattern" => {
                let pat = ch
                    .child_by_field_name("pattern")
                    .or_else(|| ch.child_by_field_name("name"))
                    .unwrap_or(ch);
                match simple_pat_name(pat, src) {
                    Some(n) => names.push(n),
                    None => {
                        return Err(Error::Other(
                            "inline needs simple identifier parameters".into(),
                        ));
                    }
                }
            }
            _ => {}
        }
    }
    Ok(names)
}

fn simple_pat_name(node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String> {
    match node.kind() {
        "identifier" => Some(node_src(src, node)),
        "mut_pattern" => {
            let mut c = node.walk();
            node.named_children(&mut c)
                .find(|ch| ch.kind() == "identifier")
                .map(|id| node_src(src, id))
        }
        _ => None,
    }
}

fn node_src(src: &[u8], n: tree_sitter::Node<'_>) -> String {
    let a = n.start_byte().min(src.len());
    let b = n.end_byte().min(src.len()).max(a);
    String::from_utf8_lossy(&src[a..b]).into_owned()
}

fn extend_call(src: &[u8], name_end: usize) -> Result<(usize, Vec<String>)> {
    let mut i = name_end;
    while i < src.len() && src[i].is_ascii_whitespace() {
        i += 1;
    }
    if i >= src.len() || src[i] != b'(' {
        return Err(Error::Other("inline needs a call site".into()));
    }
    let close = matching_paren(src, i)?;
    Ok((close + 1, split_args(&src[i + 1..close])))
}

fn matching_paren(src: &[u8], open: usize) -> Result<usize> {
    let mut i = open;
    let mut depth = 0i32;
    while i < src.len() {
        let b = src[i];
        if b == b'/' && i + 1 < src.len() {
            if src[i + 1] == b'/' {
                i += 2;
                while i < src.len() && src[i] != b'\n' {
                    i += 1;
                }
                continue;
            }
            if src[i + 1] == b'*' {
                i += 2;
                while i + 1 < src.len() && !(src[i] == b'*' && src[i + 1] == b'/') {
                    i += 1;
                }
                i = i.saturating_add(2);
                continue;
            }
        }
        if b == b'"' || b == b'\'' {
            let quote = b;
            i += 1;
            while i < src.len() {
                if src[i] == b'\\' {
                    i = i.saturating_add(2);
                    continue;
                }
                if src[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        if b == b'(' {
            depth += 1;
        } else if b == b')' {
            depth -= 1;
            if depth == 0 {
                return Ok(i);
            }
        }
        i += 1;
    }
    Err(Error::Other("inline call is unclosed".into()))
}

fn split_args(inner: &[u8]) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    let mut i = 0usize;
    while i < inner.len() {
        let b = inner[i];
        if b == b'"' || b == b'\'' {
            let quote = b;
            i += 1;
            while i < inner.len() {
                if inner[i] == b'\\' {
                    i = i.saturating_add(2);
                    continue;
                }
                if inner[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        match b {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.saturating_sub(1),
            b',' if depth == 0 => {
                push_arg(&mut out, &inner[start..i]);
                start = i + 1;
            }
            _ => {}
        }
        i += 1;
    }
    push_arg(&mut out, &inner[start..]);
    out
}

fn push_arg(out: &mut Vec<String>, piece: &[u8]) {
    let s = String::from_utf8_lossy(piece).trim().to_string();
    if !s.is_empty() {
        out.push(s);
    }
}

fn bind_and_body(params: &[String], args: &[String], body: &str) -> String {
    if params.is_empty() {
        return body.to_string();
    }
    let mut s = String::from("{\n");
    for (p, a) in params.iter().zip(args) {
        s.push_str("    let ");
        s.push_str(p);
        s.push_str(" = ");
        s.push_str(a);
        s.push_str(";\n");
    }
    s.push_str(body);
    if !body.ends_with('\n') {
        s.push('\n');
    }
    s.push('}');
    s
}

fn rust_postfix(src: &[u8], after_call: usize) -> bool {
    let mut i = after_call;
    while i < src.len() && src[i].is_ascii_whitespace() {
        i += 1;
    }
    i < src.len() && matches!(src[i], b'?' | b'.')
}

pub fn edit_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    definition: &[u8],
) -> Result<(Snapshot, ObservedClass)> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let definition = item_text(store, snap, id, definition)?;
    let (root_old, part) = ingest_item_tree(
        "edit-def",
        store,
        snap,
        &rec.file,
        lang,
        rec.parent,
        &definition,
    )?;
    let mapped = remap_tree(store, part.entities, root_old, id, Some(snap))?;
    let new_rec = mapped
        .get(&id)
        .cloned()
        .ok_or_else(|| Error::Other("edit-def lost the root item".into()))?;
    if new_rec.name != rec.name {
        return Err(Error::Other(format!(
            "edit-def cannot rename {} to {}; use svc rename",
            rec.name, new_rec.name
        )));
    }
    if new_rec.kind != rec.kind {
        return Err(Error::Other(format!(
            "edit-def cannot change {} from {:?} to {:?}; delete and add-def instead",
            rec.name, rec.kind, new_rec.kind
        )));
    }
    let new_content = new_rec.content;
    let new_bytes = new_rec.bytes;
    let mut next = snap.clone();
    for cid in subtree(snap, id) {
        if cid != id {
            next.entities.remove(&cid);
        }
    }
    if let Some(dest) = next.entities.get_mut(&id) {
        dest.content = new_content;
        dest.bytes = new_bytes;
    }
    for (cid, mut child) in mapped {
        if cid == id {
            continue;
        }
        child.file = rec.file.clone();
        next.insert(cid, child)?;
    }
    let old_c = store.get_content(rec.content)?;
    let new_c = store.get_content(new_content)?;
    let (old_r, old_m) = render_entity(snap, store, id, true)?;
    let (new_r, new_m) = render_entity(&next, store, id, true)?;
    let class = classify(
        &old_c,
        &new_c,
        rec.bytes,
        new_bytes,
        &old_r,
        &new_r,
        &Default::default(),
        &Default::default(),
        old_m.as_deref().unwrap_or(&[]),
        new_m.as_deref().unwrap_or(&[]),
    );
    Ok((next, class))
}

pub fn add_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    parent: Option<EntityId>,
    ordinal: u32,
    definition: &[u8],
    intent: Intent,
) -> Result<Snapshot> {
    add_def_at(
        store, langs, snap, id, parent, None, ordinal, definition, intent,
    )
}

/// Parent's file, else the first tracked source file. An explicit `file` wins.
pub fn resolve_add_def_file(
    snap: &Snapshot,
    langs: &Langs,
    parent: Option<EntityId>,
    file: Option<RelPath>,
) -> Result<RelPath> {
    if let Some(file) = file {
        return Ok(file);
    }
    match parent {
        Some(p) => Ok(snap
            .entities
            .get(&p)
            .ok_or(Error::NoSuchEntity(p))?
            .file
            .clone()),
        None => Ok(snap
            .files
            .keys()
            .find(|p| langs.for_path(p).is_some())
            .cloned()
            .ok_or_else(|| Error::Other("no tracked source file to add into".into()))?),
    }
}

pub fn add_def_at(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    parent: Option<EntityId>,
    file: Option<RelPath>,
    ordinal: u32,
    definition: &[u8],
    _intent: Intent,
) -> Result<Snapshot> {
    let file = resolve_add_def_file(snap, langs, parent, file)?;
    let lang = langs
        .for_path(&file)
        .ok_or_else(|| Error::NoLanguage(file.clone()))?;
    let indent = parent
        .map(|p| sibling_indent(store, snap, p))
        .unwrap_or_default();
    let definition = add_def_text(parent, &indent, definition);
    let (root_old, part) =
        ingest_item_tree("add-def", store, snap, &file, lang, parent, &definition)?;
    let mapped = remap_tree(store, part.entities, root_old, id, None)?;
    let mut next = snap.clone();
    next.ensure_file(file.clone());
    let mut root = mapped
        .get(&id)
        .cloned()
        .ok_or_else(|| Error::Other("add-def lost the root item".into()))?;
    root.parent = parent;
    root.file = file.clone();
    root.ordinal = ordinal;
    if parent.is_none() {
        next.make_room_at_root(&file, ordinal, id);
    }
    next.insert(id, root)?;
    for (cid, mut rec) in mapped {
        if cid == id {
            continue;
        }
        rec.file = file.clone();
        next.insert(cid, rec)?;
    }
    if let Some(p) = parent {
        let mut kids = child_ids_of(store, &next, p)?;
        kids.retain(|c| *c != id);
        let at = (ordinal as usize).min(kids.len());
        kids.insert(at, id);
        apply_child_holes(store, &mut next, p, &kids)?;
    }
    Ok(next)
}

pub fn classify_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    definition: &[u8],
) -> Result<ObservedClass> {
    let (_, class) = edit_def(store, langs, snap, id, definition)?;
    Ok(class)
}

pub fn show(store: &dyn Store, snap: &Snapshot, id: EntityId) -> Result<String> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let content = store.get_content(rec.content)?;
    Ok(format_tokens(snap, &content.tokens, &rec.name))
}

pub fn format_tokens(snap: &Snapshot, tokens: &[Token], self_name: &str) -> String {
    let mut out = String::new();
    for t in tokens {
        match t {
            Token::Punct(p) | Token::Kw(p) | Token::Lit(p) => out.push_str(p),
            Token::Binder(s, _) => out.push_str(&format!("${}", s.0)),
            Token::Ident(IdentRef::Local(s, _)) => out.push_str(&format!("${}", s.0)),
            Token::Ident(IdentRef::Free(n)) => out.push_str(n),
            Token::Ident(IdentRef::Entity(eid)) if *eid == EntityId::SELF => {
                out.push_str(self_name)
            }
            Token::Ident(IdentRef::Entity(eid)) | Token::Child(eid) => {
                let name = snap
                    .entities
                    .get(eid)
                    .map(|e| e.name.as_str())
                    .unwrap_or("?");
                out.push_str(&format!("#{name}⟨{}⟩", eid.short()));
            }
        }
        out.push(' ');
    }
    out
}

/// Layout: alpha/docs-only edits, commutative relocations, and file deltas of source
/// files (their entities are counted on their own; a tail is trivia, or whitespace).
/// Semantic: everything else, including any change to a file svc has no language for.
pub fn status_report(store: &dyn Store, prev: &Snapshot, next: &Snapshot) -> Result<StatusReport> {
    let deltas = super::diff(store, prev, next)?;
    let is_source = |p: &RelPath| lang_for_ext(p.extension()).is_some();
    let mut layout = 0usize;
    let mut semantic = 0usize;
    for d in &deltas {
        let is_layout = match d {
            Delta::Edited(_, ObservedClass::Alpha | ObservedClass::DocsOnly) => true,
            Delta::Relocated { .. } => true,
            Delta::FileAdded(p) | Delta::FileRemoved(p) => is_source(p),
            Delta::FileTail { path, whitespace_only } => *whitespace_only || is_source(path),
            _ => false,
        };
        if is_layout {
            layout += 1;
        } else {
            semantic += 1;
        }
    }
    Ok(StatusReport {
        entities: next.entities.len(),
        deltas,
        layout,
        semantic,
    })
}

#[derive(Clone, Debug)]
pub struct StatusReport {
    pub entities: usize,
    pub deltas: Vec<Delta>,
    pub layout: usize,
    pub semantic: usize,
}

impl StatusReport {
    pub fn summary(&self) -> String {
        if self.deltas.is_empty() {
            format!("{} entities, 0 changes", self.entities)
        } else if self.semantic == 0 {
            format!("no semantic changes; {} layout", self.layout)
        } else {
            format!(
                "{} semantic; {} layout ({} entities)",
                self.semantic, self.layout, self.entities
            )
        }
    }
}

/// Entities whose content or bytes *name* `id`. Child holes are containment,
/// not uses — counting them made every nested delete refuse.
pub fn referrers(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Vec<EntityId>> {
    let mut out = Vec::new();
    for (oid, rec) in &snap.entities {
        if *oid == id {
            continue;
        }
        let in_content = store
            .get_content(rec.content)?
            .tokens
            .iter()
            .any(|t| match t {
                Token::Ident(IdentRef::Entity(e)) => *e == id,
                _ => false,
            });
        let in_bytes = || -> Result<bool> {
            Ok(store
                .get_bytes_blob(rec.bytes)?
                .chunks()
                .iter()
                .any(|c| match c {
                    Chunk::Name(e) => *e == id,
                    _ => false,
                }))
        };
        if in_content || in_bytes()? {
            out.push(*oid);
        }
    }
    Ok(out)
}

fn child_ids_in_chunks(chunks: &[Chunk]) -> Vec<EntityId> {
    chunks
        .iter()
        .filter_map(|c| match c {
            Chunk::Child(id) => Some(*id),
            _ => None,
        })
        .collect()
}

fn child_ids_of(store: &dyn Store, snap: &Snapshot, parent: EntityId) -> Result<Vec<EntityId>> {
    let rec = snap
        .entities
        .get(&parent)
        .ok_or(Error::NoSuchEntity(parent))?;
    Ok(child_ids_in_chunks(
        store.get_bytes_blob(rec.bytes)?.chunks(),
    ))
}

fn apply_child_holes(
    store: &dyn Store,
    snap: &mut Snapshot,
    parent: EntityId,
    want: &[EntityId],
) -> Result<()> {
    let rec = snap
        .entities
        .get(&parent)
        .ok_or(Error::NoSuchEntity(parent))?
        .clone();
    let bytes = store.get_bytes_blob(rec.bytes)?;
    let content = store.get_content(rec.content)?;
    let new_bytes = rewrite_bytes_children(&bytes, want)?;
    let new_content = Content {
        tokens: rewrite_content_children(content.tokens, want),
    };
    let bytes_id = store.put_bytes_blob(&new_bytes)?;
    let content_id = store.put_content(&new_content)?;
    let rec = snap.entities.get_mut(&parent).unwrap();
    rec.bytes = bytes_id;
    rec.content = content_id;
    Ok(())
}

fn rewrite_bytes_children(bytes: &Bytes, want: &[EntityId]) -> Result<Bytes> {
    let have = child_ids_in_chunks(bytes.chunks());
    if have == want {
        return Ok(Bytes::new(
            bytes.src().to_vec(),
            bytes.chunks().to_vec(),
            bytes.local_ranges().to_vec(),
        )?);
    }
    let want_set: BTreeSet<EntityId> = want.iter().copied().collect();
    let mut src = bytes.src().to_vec();
    let mut chunks: Vec<Chunk> = bytes
        .chunks()
        .iter()
        .cloned()
        .filter(|c| match c {
            Chunk::Child(id) => want_set.contains(id),
            _ => true,
        })
        .collect();
    for (i, id) in want.iter().enumerate() {
        if child_ids_in_chunks(&chunks).contains(id) {
            continue;
        }
        chunks = insert_child_chunk(&mut src, chunks, *id, i);
    }
    let have = child_ids_in_chunks(&chunks);
    if have != want {
        let mut iter = want.iter();
        for c in &mut chunks {
            if let Chunk::Child(id) = c
                && let Some(next) = iter.next()
            {
                *id = *next;
            }
        }
    }
    Bytes::new(src, chunks, bytes.local_ranges().to_vec())
}

fn insert_child_chunk(
    src: &mut Vec<u8>,
    mut chunks: Vec<Chunk>,
    id: EntityId,
    ordinal: usize,
) -> Vec<Chunk> {
    let positions: Vec<usize> = chunks
        .iter()
        .enumerate()
        .filter_map(|(i, c)| matches!(c, Chunk::Child(_)).then_some(i))
        .collect();
    let insert_at = if ordinal < positions.len() {
        positions[ordinal]
    } else if let Some(&last) = positions.last() {
        last + 1
    } else {
        split_close_brace(src, &mut chunks)
    };
    // A member's bytes end at its last token; whatever follows must begin on a new
    // line. The next sibling carries its own leading newline, and so does the parent's
    // closing text in every rendered file — only a bare `}` (split_close_brace) or a
    // literal that starts mid-line needs one added here.
    let next_starts_on_new_line = match chunks.get(insert_at) {
        Some(Chunk::Child(_)) => true,
        Some(Chunk::Literal(r)) => src.get(r.start as usize) == Some(&b'\n'),
        Some(Chunk::Name(_)) | None => false,
    };
    chunks.insert(insert_at, Chunk::Child(id));
    if !next_starts_on_new_line {
        let extra_start = src.len() as u32;
        src.extend_from_slice(b"\n");
        let extra = ByteRange {
            start: extra_start,
            end: src.len() as u32,
        };
        chunks.insert(insert_at + 1, Chunk::Literal(extra));
    }
    chunks
}

fn split_close_brace(src: &[u8], chunks: &mut Vec<Chunk>) -> usize {
    for i in (0..chunks.len()).rev() {
        let Chunk::Literal(r) = chunks[i] else {
            continue;
        };
        let slice = &src[r.start as usize..r.end as usize];
        let Some(rel) = slice.iter().rposition(|&b| b == b'}') else {
            continue;
        };
        let brace = r.start + rel as u32;
        chunks.remove(i);
        let mut at = i;
        if brace > r.start {
            chunks.insert(
                at,
                Chunk::Literal(ByteRange {
                    start: r.start,
                    end: brace,
                }),
            );
            at += 1;
        }
        chunks.insert(
            at,
            Chunk::Literal(ByteRange {
                start: brace,
                end: r.end,
            }),
        );
        return at;
    }
    chunks.len()
}

fn rewrite_content_children(tokens: Vec<Token>, want: &[EntityId]) -> Vec<Token> {
    let content_kids = |tokens: &[Token]| -> Vec<EntityId> {
        tokens
            .iter()
            .filter_map(|t| match t {
                Token::Child(id) => Some(*id),
                _ => None,
            })
            .collect()
    };
    if content_kids(&tokens) == want {
        return tokens;
    }
    let want_set: BTreeSet<EntityId> = want.iter().copied().collect();
    let mut tokens: Vec<Token> = tokens
        .into_iter()
        .filter(|t| match t {
            Token::Child(id) => want_set.contains(id),
            _ => true,
        })
        .collect();
    for (i, id) in want.iter().enumerate() {
        if content_kids(&tokens).contains(id) {
            continue;
        }
        let positions: Vec<usize> = tokens
            .iter()
            .enumerate()
            .filter_map(|(j, t)| matches!(t, Token::Child(_)).then_some(j))
            .collect();
        let at = if i < positions.len() {
            positions[i]
        } else if let Some(&last) = positions.last() {
            last + 1
        } else {
            tokens
                .iter()
                .rposition(|t| matches!(t, Token::Punct(p) if p.as_ref() == "}"))
                .unwrap_or(tokens.len())
        };
        tokens.insert(at, Token::Child(*id));
    }
    if content_kids(&tokens) != want {
        let mut iter = want.iter();
        for t in &mut tokens {
            if let Token::Child(id) = t
                && let Some(next) = iter.next()
            {
                *id = *next;
            }
        }
    }
    tokens
}

fn subtree(snap: &Snapshot, id: EntityId) -> BTreeSet<EntityId> {
    let mut out = BTreeSet::from([id]);
    let mut grow = true;
    while grow {
        grow = false;
        for (cid, rec) in &snap.entities {
            if let Some(p) = rec.parent
                && out.contains(&p)
                && out.insert(*cid)
            {
                grow = true;
            }
        }
    }
    out
}

pub fn commit_snapshot(store: &dyn Store, snap: &Snapshot) -> Result<crate::ids::SnapshotId> {
    let id = store.put_snapshot(snap)?;
    store.set_root(id)?;
    store.set_head(snap.change, id)?;
    Ok(id)
}

pub fn rust_langs() -> Langs {
    Langs::new(vec![Box::new(crate::RustLang)])
}

/// Same nested-child keep as `edit_def`. Returns the new snapshot plus the
/// edited root's hashes so O3 can assert callee holes without walking entities.
pub fn redefine(
    store: &dyn Store,
    langs: &Langs,
    snapshot: &Snapshot,
    id: EntityId,
    text: &[u8],
) -> Result<(Snapshot, crate::ids::ContentId, crate::ids::BytesId)> {
    let (next, _) = edit_def(store, langs, snapshot, id, text)?;
    let rec = next.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let hashes = (rec.content, rec.bytes);
    Ok((next, hashes.0, hashes.1))
}

/// The one item a verb body must be: parses without error nodes, exactly one root
/// entity. Ingest itself is lenient (a checked-in file may be mid-edit); the typed
/// write path is not.
/// Parse and ingest one definition. Under a parent whose members do not parse on their
/// own (a JS class), the text is wrapped in the language's member shell and the member,
/// not the shell, is returned as the root.
fn ingest_item_tree(
    verb: &str,
    store: &dyn Store,
    snap: &Snapshot,
    file: &RelPath,
    lang: &dyn crate::lang::Lang,
    parent: Option<EntityId>,
    text: &[u8],
) -> Result<(EntityId, Snapshot)> {
    let parent_kind = parent.and_then(|p| snap.entities.get(&p)).map(|r| r.kind);
    let shell = parent_kind.and_then(|k| lang.member_shell(k));
    let wrapped: Vec<u8> = match shell {
        Some((open, close)) => [open.as_bytes(), text, close.as_bytes()].concat(),
        None => text.to_vec(),
    };
    if super::parse(&wrapped, lang)?.root_node().has_error() {
        return Err(Error::Parse(format!(
            "{verb} definition does not parse as {}",
            lang.name()
        )));
    }
    let mut env = env_from_snapshot(snap);
    fill_self_methods_from_snapshot(&mut env, snap, parent);
    let mut part = ingest_file_with_env(&wrapped, file.clone(), lang, store, snap.change, &env)?;
    let roots: Vec<EntityId> = part
        .entities
        .iter()
        .filter(|(_, r)| r.parent.is_none())
        .map(|(id, _)| *id)
        .collect();
    let [root] = roots.as_slice() else {
        return Err(Error::Other(format!(
            "{verb} definition must parse to exactly one item"
        )));
    };
    let root = *root;
    if shell.is_none() {
        return Ok((root, part));
    }
    let members: Vec<EntityId> = part
        .entities
        .iter()
        .filter(|(_, r)| r.parent == Some(root))
        .map(|(id, _)| *id)
        .collect();
    let [member] = members.as_slice() else {
        return Err(Error::Other(format!(
            "{verb} definition must be exactly one member"
        )));
    };
    let member = *member;
    part.entities.remove(&root);
    part.entities.get_mut(&member).unwrap().parent = None;
    Ok((member, part))
}

fn derived_id(parent: EntityId, rec: &EntityRecord) -> EntityId {
    let mut h = blake3::Hasher::new();
    h.update(parent.0.as_bytes());
    h.update(&[0]);
    h.update(format!("{:?}", rec.kind).as_bytes());
    h.update(&[0]);
    h.update(rec.name.as_bytes());
    h.update(&[0]);
    h.update(&rec.ordinal.to_le_bytes());
    let hash = h.finalize();
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&hash.as_bytes()[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x80;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    EntityId(uuid::Uuid::from_bytes(bytes))
}

fn remap_tree(
    store: &dyn Store,
    tree: BTreeMap<EntityId, EntityRecord>,
    root_old: EntityId,
    root_new: EntityId,
    prev: Option<&Snapshot>,
) -> Result<BTreeMap<EntityId, EntityRecord>> {
    let mut id_map = BTreeMap::new();
    id_map.insert(root_old, root_new);
    let mut taken = BTreeSet::from([root_new]);
    let mut queue = vec![root_old];
    while let Some(old) = queue.pop() {
        let parent_new = id_map[&old];
        let mut kids: Vec<(EntityId, EntityRecord)> = tree
            .iter()
            .filter(|(_, r)| r.parent == Some(old))
            .map(|(i, r)| (*i, r.clone()))
            .collect();
        kids.sort_by_key(|(_, r)| r.ordinal);
        for (old_id, rec) in kids {
            let new_id = match prev {
                Some(prev) => {
                    let key = SigKey::new(Some(parent_new), &rec.file, rec.kind, rec.name.clone());
                    prev.entities
                        .iter()
                        .find_map(|(pid, r)| {
                            (!taken.contains(pid) && r.sig_key() == key).then_some(*pid)
                        })
                        .unwrap_or_else(|| derived_id(parent_new, &rec))
                }
                None => derived_id(parent_new, &rec),
            };
            taken.insert(new_id);
            id_map.insert(old_id, new_id);
            queue.push(old_id);
        }
    }
    let mut out = BTreeMap::new();
    for (old, rec) in &tree {
        let new_id = *id_map.get(old).unwrap_or(old);
        let mut rec = rec.clone();
        rec.parent = rec.parent.map(|p| *id_map.get(&p).unwrap_or(&p));
        let bytes = remap_bytes(&store.get_bytes_blob(rec.bytes)?, &id_map)?;
        let content = Content {
            tokens: remap_tokens(store.get_content(rec.content)?.tokens, &id_map),
        };
        rec.bytes = store.put_bytes_blob(&bytes)?;
        rec.content = store.put_content(&content)?;
        out.insert(new_id, rec);
    }
    Ok(out)
}

fn remap_id(id: EntityId, map: &BTreeMap<EntityId, EntityId>) -> EntityId {
    if id == EntityId::SELF {
        id
    } else {
        *map.get(&id).unwrap_or(&id)
    }
}

fn remap_bytes(bytes: &Bytes, map: &BTreeMap<EntityId, EntityId>) -> Result<Bytes> {
    let chunks: Vec<Chunk> = bytes
        .chunks()
        .iter()
        .map(|c| match c {
            Chunk::Child(id) => Chunk::Child(remap_id(*id, map)),
            Chunk::Name(id) => Chunk::Name(remap_id(*id, map)),
            other => other.clone(),
        })
        .collect();
    let locals: Vec<(ByteRange, IdentRef)> = bytes
        .local_ranges()
        .iter()
        .map(|(r, ident)| {
            let ident = match ident {
                IdentRef::Entity(id) => IdentRef::Entity(remap_id(*id, map)),
                other => other.clone(),
            };
            (*r, ident)
        })
        .collect();
    Bytes::new(bytes.src().to_vec(), chunks, locals)
}

fn remap_tokens(tokens: Vec<Token>, map: &BTreeMap<EntityId, EntityId>) -> Vec<Token> {
    tokens
        .into_iter()
        .map(|t| match t {
            Token::Child(id) => Token::Child(remap_id(id, map)),
            Token::Ident(IdentRef::Entity(id)) => Token::Ident(IdentRef::Entity(remap_id(id, map))),
            other => other,
        })
        .collect()
}

/// Keep the entity's leading trivia (blank lines / docs attached by extent)
/// and tolerate a missing trailing newline (source_file vs item range tie).
fn item_text(store: &dyn Store, snap: &Snapshot, id: EntityId, text: &[u8]) -> Result<Vec<u8>> {
    let (old, _) = super::render_entity(snap, store, id, false)?;
    let lead = old.iter().take_while(|b| b.is_ascii_whitespace()).count();
    let mut out = Vec::new();
    if !text.first().is_some_and(|b| b.is_ascii_whitespace()) {
        out.extend_from_slice(&old[..lead]);
    }
    out.extend_from_slice(text);
    if !out.ends_with(b"\n") {
        out.push(b'\n');
    }
    Ok(out)
}

/// After roots of `file` were reordered: the first root starts at column 0 with no blank
/// line above it, every later root starts on a fresh line with one blank line before it —
/// unless it already begins with a newline, in which case its own trivia is kept. The
/// separator between two items lives in the second one's leading text, so an item moved
/// to or from the front would otherwise render glued (`}fn`) or leave a blank first line.
fn normalize_root_separators(store: &dyn Store, snap: &mut Snapshot, file: &RelPath) -> Result<()> {
    for (i, id) in snap.file_roots(file).into_iter().enumerate() {
        let rec = &snap.entities[&id];
        let bytes = store.get_bytes_blob(rec.bytes)?;
        let lead = bytes
            .chunks()
            .first()
            .and_then(|c| match c {
                Chunk::Literal(r) => Some(
                    bytes.src()[r.start as usize..r.end as usize]
                        .iter()
                        .take_while(|b| **b == b'\n')
                        .count(),
                ),
                _ => None,
            });
        let want = match (i, lead) {
            (0, Some(l)) if l > 0 => 0,
            (_, Some(0)) if i > 0 => 2,
            _ => continue,
        };
        let fixed = bytes.with_leading_newlines(want)?;
        let bytes_id = store.put_bytes_blob(&fixed)?;
        snap.entities.get_mut(&id).unwrap().bytes = bytes_id;
    }
    Ok(())
}

/// Indentation of `parent`'s existing members (the whitespace after the last newline
/// before the first member's text); four spaces when it has none yet.
fn sibling_indent(store: &dyn Store, snap: &Snapshot, parent: EntityId) -> Vec<u8> {
    let first = snap
        .entities
        .iter()
        .filter(|(_, r)| r.parent == Some(parent))
        .min_by_key(|(_, r)| r.ordinal)
        .map(|(id, _)| *id);
    let indent = first
        .and_then(|id| render_entity(snap, store, id, false).ok())
        .and_then(|(bytes, _)| {
            let lead = bytes.iter().take_while(|b| b.is_ascii_whitespace()).count();
            let last_nl = bytes[..lead].iter().rposition(|b| *b == b'\n')?;
            Some(bytes[last_nl + 1..lead].to_vec())
        });
    indent
        .filter(|i| !i.is_empty())
        .unwrap_or_else(|| b"    ".to_vec())
}

/// A new item needs a blank line before it or render glues `}fn` / `;fn`. Nested items
/// (an impl method, a class member) are also indented one level when the body an
/// agent passes is written at column 0; a body that arrives indented is kept as is.
/// Only text that begins with its own newline is taken as already laid out.
fn add_def_text(parent: Option<EntityId>, indent: &[u8], text: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let laid_out = text.first() == Some(&b'\n');
    let indented = text.first().is_some_and(|b| *b == b' ' || *b == b'\t');
    if !laid_out {
        out.extend_from_slice(b"\n\n");
    }
    if parent.is_some() && !laid_out && !indented {
        for (i, line) in text.split(|b| *b == b'\n').enumerate() {
            if i > 0 {
                out.push(b'\n');
            }
            if !line.is_empty() {
                out.extend_from_slice(indent);
                out.extend_from_slice(line);
            }
        }
    } else {
        out.extend_from_slice(text);
    }
    if !out.ends_with(b"\n") {
        out.push(b'\n');
    }
    out
}

crates/svc-core/tests/o1_round_trip.rs.Text:
use svc_core::RustLang;
use svc_core::engine::{ingest_file, lookup_name, relocate, render, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::lang::Langs;
use svc_core::store::MemStore;

fn round_trip(src: &str) -> String {
    let store = MemStore::new();
    let lang = RustLang;
    let path = RelPath::new("src/lib.rs").unwrap();
    let snap = ingest_file(src.as_bytes(), path, &lang, &store, ChangeId::new()).unwrap();
    let langs = Langs::new(vec![Box::new(RustLang)]);
    let rendered = render(&snap, &store, &langs, false).unwrap();
    let bytes = rendered.files.values().next().cloned().unwrap_or_default();
    String::from_utf8(bytes).unwrap()
}

#[test]
fn o1_simple_file() {
    let src = r#"struct Config { path: String }

fn read(path: &str) -> String {
    path.to_string()
}

fn main() {
    let _ = read("x");
}
"#;
    assert_eq!(round_trip(src), src);
}

#[test]
fn o1_impl_method() {
    let src = r#"struct Config;

impl Config {
    fn new() -> Self {
        Config
    }
}
"#;
    assert_eq!(round_trip(src), src);
}

#[test]
fn o1_use_and_trailing_newline() {
    let src = "use std::fmt;\n\nfn f() {}\n";
    assert_eq!(round_trip(src), src);
}

#[test]
fn o1_opaque_manifest_round_trips_without_a_language() {
    use std::collections::BTreeMap;
    let store = MemStore::new();
    let langs = rust_langs();
    let mut files = BTreeMap::new();
    files.insert(RelPath::new("src/lib.rs").unwrap(), b"fn f() {}\n".to_vec());
    files.insert(
        RelPath::new("Cargo.toml").unwrap(),
        b"[package]\nname = \"x\"\n".to_vec(),
    );
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let toml = RelPath::new("Cargo.toml").unwrap();
    assert_eq!(
        snap.files.get(&toml).unwrap().trailing,
        b"[package]\nname = \"x\"\n"
    );
    assert!(!snap.entities.values().any(|e| e.file == toml));
    let rendered = render(&snap, &store, &langs, false).unwrap();
    assert_eq!(
        rendered.files.get(&toml).unwrap().as_slice(),
        b"[package]\nname = \"x\"\n"
    );
}

#[test]
fn relocate_to_a_missing_path_is_still_rendered() {
    use std::collections::BTreeMap;
    let store = MemStore::new();
    let langs = rust_langs();
    let src = RelPath::new("src/lib.rs").unwrap();
    let dest = RelPath::new("src/b.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(src.clone(), b"fn a() {}\nfn b() {}\n".to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let id = lookup_name(&snap, "b").unwrap();
    let next = relocate(&snap, &store, id, dest.clone(), 0).unwrap();
    assert!(
        next.files.contains_key(&dest),
        "relocate must create a FileRecord"
    );
    let rendered = render(&next, &store, &langs, false).unwrap();
    let dest_src = String::from_utf8_lossy(rendered.files.get(&dest).unwrap());
    assert!(dest_src.contains("fn b"), "{dest_src}");
    let src_src = String::from_utf8_lossy(rendered.files.get(&src).unwrap());
    assert!(!src_src.contains("fn b"), "{src_src}");
}

#[test]
fn o1_svc_core_source() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
    let mut files = Vec::new();
    visit(&root, &mut files);
    assert!(!files.is_empty());
    for path in files {
        let src = std::fs::read_to_string(&path).unwrap();
        let got = round_trip(&src);
        assert_eq!(got, src, "round-trip failed for {}", path.display());
    }
}

fn visit(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    for e in std::fs::read_dir(dir).unwrap() {
        let e = e.unwrap();
        let p = e.path();
        if p.is_dir() {
            visit(&p, out);
        } else if p.extension().and_then(|s| s.to_str()) == Some("rs") {
            out.push(p);
        }
    }
}

crates/svc-core/tests/root_ordinal.rs.Text:
//! `add-def --ordinal n` / `relocate … --ordinal n` at a file root place the entity at
//! that position: a root already at `n` and everything after it move down one, so
//! render order is the asked-for order, not a tie broken by id.
//! The blank line between roots lives in the second one, so an item moved to or from the
//! front has its leading newlines set to what its new position needs.
use std::collections::BTreeMap;

use svc_core::engine::{add_def, lookup_name, relocate, render, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, EntityId, RelPath};
use svc_core::store::MemStore;
use svc_core::Intent;

const SRC: &str = "fn a() {}\n\nfn b() {}\n\nfn c() {}\n";

fn order(out: &str) -> Vec<&str> {
    out.lines()
        .filter_map(|l| l.strip_prefix("fn ").and_then(|r| r.split('(').next()))
        .collect()
}

#[test]
fn add_def_at_a_taken_root_ordinal_shifts_the_rest_down() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let b = lookup_name(&snap, "b").unwrap();
    assert_eq!(snap.entities[&b].ordinal, 1);

    let next = add_def(&store, &langs, &snap, EntityId::new(), None, 1, b"fn n() {}", Intent::Feature).unwrap();
    let out = String::from_utf8(render(&next, &store, &langs, false).unwrap().files[&path].clone()).unwrap();
    assert_eq!(order(&out), ["a", "n", "b", "c"], "{out}");
    let ords: Vec<u32> = next.file_roots(&path).iter().map(|id| next.entities[id].ordinal).collect();
    assert!(ords.windows(2).all(|w| w[0] < w[1]), "ordinals must be distinct and ordered: {ords:?}");
}

#[test]
fn relocate_to_a_taken_root_ordinal_shifts_the_rest_down() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let c = lookup_name(&snap, "c").unwrap();

    let next = relocate(&snap, &store, c, path.clone(), 0).unwrap();
    let names: Vec<&str> = next
        .file_roots(&path)
        .iter()
        .map(|id| next.entities[id].name.as_str())
        .collect();
    assert_eq!(names, ["c", "a", "b"]);
    let out = String::from_utf8(render(&next, &store, &langs, false).unwrap().files[&path].clone()).unwrap();
    assert!(out.find("fn c()").unwrap() < out.find("fn a()").unwrap(), "{out}");
}

#[test]
fn relocating_to_the_front_and_back_keeps_items_separated() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let a = lookup_name(&snap, "a").unwrap();
    let c = lookup_name(&snap, "c").unwrap();

    let front = relocate(&snap, &store, c, path.clone(), 0).unwrap();
    let out = String::from_utf8(render(&front, &store, &langs, false).unwrap().files[&path].clone()).unwrap();
    assert_eq!(out, "fn c() {}\n\nfn a() {}\n\nfn b() {}\n");

    let back = relocate(&snap, &store, a, path.clone(), 3).unwrap();
    let out = String::from_utf8(render(&back, &store, &langs, false).unwrap().files[&path].clone()).unwrap();
    assert_eq!(out, "fn b() {}\n\nfn c() {}\n\nfn a() {}\n");

    let reparsed = snapshot_files(
        &store,
        &langs,
        &BTreeMap::from([(path.clone(), out.into_bytes())]),
        Some(&back),
        ChangeId::new(),
    )
    .unwrap();
    assert_eq!(reparsed.entities.len(), 3);
}

crates/svc-core/tests/status_relocation..Text:
//! `svc status` reports an entity that moved to another file as a layout delta.
//! A stub used to drop every `Relocated` before it reached the report.
use std::collections::BTreeMap;

use svc_core::engine::{lookup_name, relocate, rust_langs, snapshot_files, status_report};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::store::MemStore;
use svc_core::Delta;

#[test]
fn moving_an_entity_to_another_file_is_a_layout_delta() {
    let store = MemStore::new();
    let langs = rust_langs();
    let mut files = BTreeMap::new();
    files.insert(RelPath::new("src/a.rs").unwrap(), b"fn a() {}\n".to_vec());
    files.insert(RelPath::new("src/b.rs").unwrap(), b"fn b() {}\n".to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let a = lookup_name(&snap, "a").unwrap();
    let next = relocate(&snap, &store, a, RelPath::new("src/b.rs").unwrap(), 1).unwrap();
    let rep = status_report(&store, &snap, &next).unwrap();
    assert!(
        rep.deltas.iter().any(|d| matches!(d, Delta::Relocated { id, .. } if *id == a)),
        "{:?}",
        rep.deltas
    );
    assert_eq!(rep.semantic, 0, "{:?}", rep.deltas);
    // Relocated, plus the docs-only edit that gave `a` the blank line its new position needs.
    assert_eq!(rep.layout, 2, "{:?}", rep.deltas);
}

crates/svc-repo/src/bundle.rs.Text:
//! A history bundle: the op log of one store, written so another checkout of the same tree
//! can replay it into its own store. Typed ops carry themselves; what they cannot carry is
//! resolved on import — entity ids by their path (file, then kind/name from the root
//! down), change ids by the order they are minted — and a hand edit (`Absorb`) carries the
//! files it changed. Every entry names the hash of the tree it left behind, so an import
//! knows at which op, if any, it stopped reproducing the recorded history.
//!
//! `svc history export` writes one; `svc history import` replays one; `demo/history/` keeps
//! the bundles of this repository's own svc-made changes.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use svc_core::engine::{add_def_at, delete, edit_def, inline, move_def, relocate, render, rename};
use svc_core::{
    ChangeId, EntityId, Error, Kind, Op, OpIx, OpLogEntry, RelPath, Result, Snapshot, SnapshotId,
};

use crate::history::{self, op_entity};
use crate::merge;
use crate::repo::{Provenance, Repo};

/// Where an entity sits: its file, then kind and name from the outermost parent down to
/// itself. The same tree ingested twice gives every entity a fresh id; the path is what
/// survives.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct EntityPath {
    pub file: RelPath,
    pub chain: Vec<(Kind, String)>,
}

/// A file a hand edit left: its new bytes (text when UTF-8), or removed.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum FileBody {
    Text(String),
    Bytes(Vec<u8>),
    Removed,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BundleEntry {
    pub ix: OpIx,
    pub entry: OpLogEntry,
    /// Every entity id the op names, by path in the tree the op started from (the op's own
    /// new entity, for add-def, is absent: its id is minted by the op).
    #[serde(default)]
    pub refs: BTreeMap<EntityId, EntityPath>,
    /// For `Absorb`: the files the hand edit changed.
    #[serde(default)]
    pub files: BTreeMap<RelPath, FileBody>,
    /// blake3 over the rendered tree after this op (sorted path, bytes).
    pub after_tree: String,
    /// The checkout that made it (`None` = the default one).
    #[serde(default)]
    pub workspace: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Bundle {
    /// blake3 of the rendered tree the first entry starts from; an import checks its own.
    pub base_tree: String,
    pub entries: Vec<BundleEntry>,
}

#[derive(Clone, Debug, Serialize)]
pub struct ImportReport {
    pub applied: usize,
    /// First entry whose tree after import differs from the recorded hash, if any.
    pub diverged_at: Option<OpIx>,
}

fn tree_hash(files: &BTreeMap<RelPath, Vec<u8>>) -> String {
    let mut h = blake3::Hasher::new();
    for (path, bytes) in files {
        h.update(path.as_str().as_bytes());
        h.update(&[0]);
        h.update(&(bytes.len() as u64).to_le_bytes());
        h.update(bytes);
    }
    h.finalize().to_hex().to_string()
}

fn rendered(repo: &Repo, snap: &Snapshot) -> Result<BTreeMap<RelPath, Vec<u8>>> {
    Ok(render(snap, repo.store(), repo.langs(), false)?.files)
}

fn path_of(snap: &Snapshot, id: EntityId) -> Option<EntityPath> {
    let rec = snap.entities.get(&id)?;
    let mut chain = vec![(rec.kind, rec.name.clone())];
    let mut parent = rec.parent;
    while let Some(p) = parent {
        let pr = snap.entities.get(&p)?;
        chain.push((pr.kind, pr.name.clone()));
        parent = pr.parent;
    }
    chain.reverse();
    Some(EntityPath { file: rec.file.clone(), chain })
}

fn find_by_path(snap: &Snapshot, path: &EntityPath) -> Option<EntityId> {
    snap.entities
        .iter()
        .filter(|(_, r)| r.file == path.file)
        .find(|(id, _)| path_of(snap, **id).as_ref() == Some(path))
        .map(|(id, _)| *id)
}

/// Every entity id an op names besides one it mints itself.
fn named_ids(op: &Op) -> Vec<EntityId> {
    match op {
        Op::Move { id, parent, .. } => std::iter::once(*id).chain(*parent).collect(),
        Op::Extract { id, new_parent, .. } => std::iter::once(*id).chain(*new_parent).collect(),
        Op::AddDef { parent, .. } => parent.iter().copied().collect(),
        _ => op_entity(op).into_iter().collect(),
    }
}

/// The op log from `since` on, with what an import needs beside each entry.
pub fn export(repo: &Repo, since: OpIx) -> Result<Bundle> {
    let store = repo.store();
    let ops = store.ops(since, false)?;
    let Some((_, first)) = ops.first() else {
        return Err(Error::Other(format!("no ops at or after {}", since.0)));
    };
    let base = store.get_snapshot(first.before.root)?;
    let base_tree = tree_hash(&rendered(repo, &base)?);
    let mut entries = Vec::with_capacity(ops.len());
    for (ix, e) in &ops {
        let before = store.get_snapshot(e.before.root)?;
        let after = store.get_snapshot(e.after.root)?;
        let after_files = rendered(repo, &after)?;
        let refs = named_ids(&e.op)
            .into_iter()
            .filter_map(|id| path_of(&before, id).map(|p| (id, p)))
            .collect();
        let mut files = BTreeMap::new();
        if matches!(e.op, Op::Absorb) {
            let before_files = rendered(repo, &before)?;
            for (path, bytes) in &after_files {
                if before_files.get(path) != Some(bytes) {
                    let body = match String::from_utf8(bytes.clone()) {
                        Ok(text) => FileBody::Text(text),
                        Err(_) => FileBody::Bytes(bytes.clone()),
                    };
                    files.insert(path.clone(), body);
                }
            }
            for path in before_files.keys() {
                if !after_files.contains_key(path) {
                    files.insert(path.clone(), FileBody::Removed);
                }
            }
        }
        entries.push(BundleEntry {
            ix: *ix,
            entry: e.clone(),
            refs,
            files,
            after_tree: tree_hash(&after_files),
            workspace: repo.redb().op_workspace(*ix)?.filter(|w| !w.is_empty()),
        });
    }
    Ok(Bundle { base_tree, entries })
}

struct Import<'a> {
    repo: &'a Repo,
    /// Recorded change id → the one minted here.
    changes: BTreeMap<ChangeId, ChangeId>,
    /// Recorded snapshot id → the one this import produced for it.
    snaps: BTreeMap<SnapshotId, SnapshotId>,
}

impl Import<'_> {
    fn change(&self, c: ChangeId) -> ChangeId {
        *self.changes.get(&c).unwrap_or(&c)
    }

    fn entity(&self, cur: &Snapshot, b: &BundleEntry, id: EntityId) -> Result<EntityId> {
        let path = b.refs.get(&id).ok_or_else(|| {
            Error::Other(format!("op {}: no path recorded for entity {}", b.ix.0, id.short()))
        })?;
        find_by_path(cur, path).ok_or_else(|| {
            Error::Other(format!(
                "op {}: no entity at {} {} in this tree",
                b.ix.0,
                path.file,
                path.chain.iter().map(|(k, n)| format!("{k:?} {n}")).collect::<Vec<_>>().join(" / ")
            ))
        })
    }

    fn apply(&mut self, b: &BundleEntry) -> Result<()> {
        let repo = self.repo;
        let e = &b.entry;
        // A `checkout` between ops is not an op: the entry names the root it started from,
        // and if that is not where the last op left us, switch there first.
        if let Some(from) = self.snaps.get(&e.before.root).copied() {
            if from != repo.store().root()? {
                history::checkout(repo, from)?;
            }
        }
        // Same-snapshot rewrites: the op with its ids mapped, then the engine call the verb
        // itself makes.
        let cur = repo.current()?;
        match &e.op {
            Op::Rename { id, new } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Rename { id, new: new.clone() };
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, rename(cur, id, new)?))?;
            }
            Op::Move { id, parent, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let parent = parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let op = Op::Move { id, parent, ordinal: *ordinal };
                repo.mutate(op, e.observed, |repo, cur| {
                    repo.amend(cur, move_def(repo.store(), repo.langs(), cur, id, parent, *ordinal)?)
                })?;
            }
            Op::Relocate { id, file, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Relocate { id, file: file.clone(), ordinal: *ordinal };
                repo.mutate(op, e.observed, |repo, cur| {
                    repo.amend(cur, relocate(cur, repo.store(), id, file.clone(), *ordinal)?)
                })?;
            }
            Op::Extract { id, new_parent, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let new_parent = new_parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let op = Op::Extract { id, new_parent, ordinal: *ordinal };
                repo.mutate(op, e.observed, |repo, cur| {
                    repo.amend(cur, move_def(repo.store(), repo.langs(), cur, id, new_parent, Some(*ordinal))?)
                })?;
            }
            Op::Inline { id } => {
                let id = self.entity(&cur, b, *id)?;
                repo.mutate(Op::Inline { id }, e.observed, |repo, cur| {
                    repo.amend(cur, inline(repo.store(), repo.langs(), cur, id)?)
                })?;
            }
            Op::AddDef { id, parent, ordinal, definition, intent, file } => {
                let parent = parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let (id, ordinal, intent, file) = (*id, *ordinal, intent.clone(), file.clone());
                let op = Op::AddDef {
                    id,
                    parent,
                    ordinal,
                    definition: definition.clone(),
                    intent: intent.clone(),
                    file: file.clone(),
                };
                repo.mutate(op, e.observed, |repo, cur| {
                    let next = add_def_at(
                        repo.store(),
                        repo.langs(),
                        cur,
                        id,
                        parent,
                        file.clone(),
                        ordinal,
                        definition.as_bytes(),
                        intent.clone(),
                    )?;
                    repo.amend(cur, next)
                })?;
            }
            Op::Delete { id, intent } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Delete { id, intent: intent.clone() };
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, delete(cur, repo.store(), id)?))?;
            }
            Op::EditDef { id, definition, intent } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::EditDef { id, definition: definition.clone(), intent: intent.clone() };
                repo.mutate(op, e.observed, |repo, cur| {
                    let (next, _) = edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes())?;
                    repo.amend(cur, next)
                })?;
            }
            Op::New { change } => {
                let out = history::new(repo)?;
                self.changes.insert(*change, out.change);
            }
            Op::Describe { msg } => {
                history::describe(repo, msg)?;
            }
            Op::Branch { name } => {
                let out = history::branch(repo, name)?;
                if let Some(recorded) = recorded_change(e) {
                    self.changes.insert(recorded, out.change);
                }
            }
            Op::Merge { other } => {
                let other = self.change(*other);
                let out = merge::merge(repo, &other.to_string())?;
                if let Some(recorded) = recorded_change(e) {
                    self.changes.insert(recorded, out.change);
                }
            }
            // An undo and an `op restore` are both logged as Undo; what they did is the view
            // they left, so restore that view with its ids mapped.
            Op::Undo => {
                let mut view = repo.view()?;
                if let Some(root) = self.snaps.get(&e.after.root) {
                    view.root = *root;
                }
                for (change, snap) in &e.after.heads {
                    if let Some(mapped) = self.snaps.get(snap) {
                        view.heads.insert(self.change(*change), *mapped);
                    }
                }
                repo.restore_view(&view, Op::Undo)?;
            }
            Op::Resolve { conflict, take } => {
                merge::resolve(repo, *conflict as usize, *take)?;
            }
            Op::Absorb => {
                let root = repo.root_dir();
                for (path, body) in &b.files {
                    let at = root.join(path.as_str());
                    match body {
                        FileBody::Removed => {
                            let _ = std::fs::remove_file(&at);
                        }
                        FileBody::Text(t) => write_file(&at, t.as_bytes())?,
                        FileBody::Bytes(v) => write_file(&at, v)?,
                    }
                }
                repo.absorb()?;
            }
        }
        Ok(())
    }
}

/// The change an op minted: the head that is the op's after root.
fn recorded_change(e: &OpLogEntry) -> Option<ChangeId> {
    e.after.heads.iter().find(|(_, s)| **s == e.after.root).map(|(c, _)| *c)
}

fn write_file(at: &std::path::Path, bytes: &[u8]) -> Result<()> {
    if let Some(dir) = at.parent() {
        std::fs::create_dir_all(dir).map_err(Error::backend)?;
    }
    std::fs::write(at, bytes).map_err(Error::backend)
}

/// Replay `bundle` into `repo`, whose current tree must be the bundle's base. Stops at the
/// first entry that cannot be applied; reports the first whose result differs from the record.
pub fn import(repo: &Repo, bundle: &Bundle) -> Result<ImportReport> {
    let have = tree_hash(&rendered(repo, &repo.current()?)?);
    if have != bundle.base_tree {
        return Err(Error::Other(format!(
            "this tree is not the bundle's base (tree {}…, bundle starts from {}…)",
            &have[..12],
            &bundle.base_tree[..12]
        )));
    }
    let mut im = Import { repo, changes: BTreeMap::new(), snaps: BTreeMap::new() };
    if let Some(first) = bundle.entries.first() {
        im.snaps.insert(first.entry.before.root, repo.store().root()?);
    }
    let mut diverged_at = None;
    let mut applied = 0;
    for b in &bundle.entries {
        // The op line keeps its recorded time, changeset and checkout.
        let p = Provenance { at: b.entry.at, group: b.entry.group, workspace: b.workspace.clone() };
        repo.with_provenance(p, || im.apply(b))?;
        applied += 1;
        im.snaps.insert(b.entry.after.root, repo.store().root()?);
        if diverged_at.is_none() {
            let got = tree_hash(&rendered(repo, &repo.current()?)?);
            if got != b.after_tree {
                diverged_at = Some(b.ix);
            }
        }
    }
    Ok(ImportReport { applied, diverged_at })
}

crates/svc-repo/src/replay.rs.Text:
//! O5 (the oracle set): replaying the op log from the root reproduces every snapshot. The replay
//! runs on a fresh store with no filesystem, so anything the verbs keep outside the op path
//! shows up as a divergence. Snapshot hashes include change ids, and `Branch`/`Merge` mint
//! theirs at run time, so equality is on **content** (`Snapshot::content_eq`) with ids mapped
//! as the replay goes.

use std::collections::BTreeMap;

use serde::Serialize;
use svc_core::engine::{add_def_at, delete, edit_def, inline, move_def, relocate, rename};
use svc_core::{
    ChangeId, Langs, MemStore, Op, OpIx, OpLogEntry, Result, Snapshot, SnapshotId, Store, View,
};

use crate::history::child_of;
use crate::merge::{lca, merged_snapshot};
use crate::repo::Repo;

#[derive(Clone, Debug, Serialize)]
pub struct ReplayReport {
    pub ops: usize,
    /// First op whose replayed result differs from the recorded `after.root`, if any.
    pub diverged_at: Option<OpIx>,
}

impl ReplayReport {
    pub fn ok(&self) -> bool {
        self.diverged_at.is_none()
    }
}

struct Replay<'a> {
    src: &'a dyn Store,
    store: MemStore,
    langs: &'a Langs,
    /// Recorded snapshot id → replayed snapshot id.
    snaps: BTreeMap<SnapshotId, SnapshotId>,
    changes: BTreeMap<ChangeId, ChangeId>,
}

impl Replay<'_> {
    fn change(&self, c: ChangeId) -> ChangeId {
        *self.changes.get(&c).unwrap_or(&c)
    }

    fn current(&self) -> Result<Snapshot> {
        self.store.get_snapshot(self.store.root()?)
    }

    fn commit(&self, snap: &Snapshot) -> Result<SnapshotId> {
        let id = self.store.put_snapshot(snap)?;
        self.store.set_head(snap.change, id)?;
        self.store.set_root(id)?;
        Ok(id)
    }

    fn amend(&self, cur: &Snapshot, mut next: Snapshot) -> Result<SnapshotId> {
        let cur_id = cur.id();
        if next.content_eq(cur) {
            return Ok(cur_id);
        }
        next.parents = cur.parents.clone();
        next.predecessors = vec![cur_id];
        next.change = cur.change;
        self.commit(&next)
    }

    /// Copy a recorded snapshot in (used for `Absorb`, whose result is data, not an op).
    fn import(&mut self, recorded: SnapshotId) -> Result<SnapshotId> {
        let mut snap = self.src.get_snapshot(recorded)?;
        snap.change = self.change(snap.change);
        snap.parents = snap.parents.iter().map(|p| *self.snaps.get(p).unwrap_or(p)).collect();
        snap.predecessors = snap.predecessors.iter().map(|p| *self.snaps.get(p).unwrap_or(p)).collect();
        for rec in snap.entities.values() {
            self.store.put_blob(&self.src.get_blob(&rec.content.0)?)?;
            self.store.put_blob(&self.src.get_blob(&rec.bytes.0)?)?;
        }
        self.commit(&snap)
    }

    fn restore(&self, view: &View) -> Result<()> {
        for (change, snap) in &view.heads {
            if let Some(mapped) = self.snaps.get(snap) {
                self.store.set_head(self.change(*change), *mapped)?;
            }
        }
        if let Some(root) = self.snaps.get(&view.root) {
            self.store.set_root(*root)?;
        }
        Ok(())
    }

    fn apply(&mut self, e: &OpLogEntry) -> Result<()> {
        // The entry records which root it started from. With several checkouts on one op
        // log (or a `checkout` between ops) that is not necessarily the last op's result:
        // switch to it first — a checkout switch, not a content change.
        if let Some(mapped) = self.snaps.get(&e.before.root).copied() {
            if mapped != self.store.root()? {
                self.store.set_root(mapped)?;
            }
        }
        let cur = self.current()?;
        match &e.op {
            Op::Rename { id, new } => {
                self.amend(&cur, rename(&cur, *id, new)?)?;
            }
            Op::Move { id, parent, ordinal } => {
                self.amend(&cur, move_def(&self.store, self.langs, &cur, *id, *parent, *ordinal)?)?;
            }
            Op::Relocate { id, file, ordinal } => {
                self.amend(&cur, relocate(&cur, &self.store, *id, file.clone(), *ordinal)?)?;
            }
            Op::Extract { id, new_parent, ordinal } => {
                self.amend(&cur, move_def(&self.store, self.langs, &cur, *id, *new_parent, Some(*ordinal))?)?;
            }
            Op::Inline { id } => {
                self.amend(&cur, inline(&self.store, self.langs, &cur, *id)?)?;
            }
            Op::AddDef { id, parent, ordinal, definition, intent, file } => {
                let next = add_def_at(&self.store, self.langs, &cur, *id, *parent, file.clone(), *ordinal, definition.as_bytes(), intent.clone())?;
                self.amend(&cur, next)?;
            }
            Op::Delete { id, .. } => {
                self.amend(&cur, delete(&cur, &self.store, *id)?)?;
            }
            Op::EditDef { id, definition, .. } => {
                let (next, _) = edit_def(&self.store, self.langs, &cur, *id, definition.as_bytes())?;
                self.amend(&cur, next)?;
            }
            Op::New { change } => {
                let c = self.change(*change);
                self.commit(&child_of(&cur, cur.id(), c))?;
            }
            Op::Describe { msg } => {
                let mut next = cur.clone();
                next.message = msg.clone();
                self.amend(&cur, next)?;
            }
            Op::Branch { .. } => {
                let recorded = self.src.get_snapshot(e.after.root)?;
                let c = self.fresh_change(recorded.change);
                let (base, base_id) = match cur.parents.first() {
                    Some(p) => (self.store.get_snapshot(*p)?, *p),
                    None => (cur.clone(), cur.id()),
                };
                self.commit(&child_of(&base, base_id, c))?;
            }
            Op::Merge { other } => {
                let other_id = self.store.head(self.change(*other))?;
                let cur_id = cur.id();
                let base_id = lca(&self.store, cur_id, other_id)?
                    .ok_or_else(|| svc_core::Error::Other("replay: no common ancestor".into()))?;
                let recorded = self.src.get_snapshot(e.after.root)?;
                let c = self.fresh_change(recorded.change);
                let snap = merged_snapshot(&self.store, self.langs, base_id, cur_id, other_id, c)?;
                self.commit(&snap)?;
            }
            Op::Undo => self.restore(&e.after)?,
            Op::Resolve { conflict, take } => {
                let (next, _) = crate::merge::resolved_snapshot(&self.store, &cur, *conflict as usize, *take)?;
                self.amend(&cur, next)?;
            }
            Op::Absorb => {
                self.import(e.after.root)?;
            }
        }
        Ok(())
    }

    fn fresh_change(&mut self, recorded: ChangeId) -> ChangeId {
        let c = ChangeId::new();
        self.changes.insert(recorded, c);
        c
    }
}

/// Replay `repo`'s op log on a fresh store; report the first divergence.
pub fn replay(repo: &Repo) -> Result<ReplayReport> {
    let src = repo.store();
    let ops = src.ops(OpIx(0), false)?;
    let mut r = Replay {
        src,
        store: MemStore::new(),
        langs: repo.langs(),
        snaps: BTreeMap::new(),
        changes: BTreeMap::new(),
    };
    let mut diverged_at = None;
    for (i, (ix, e)) in ops.iter().enumerate() {
        if i == 0 {
            // The init op's `after.root` is the ingested tree; replay starts from it.
            r.import(e.after.root)?;
        } else {
            r.apply(e)?;
        }
        let got = r.current()?;
        let want = src.get_snapshot(e.after.root)?;
        r.snaps.insert(e.after.root, got.id());
        if !got.content_eq(&want) && diverged_at.is_none() {
            diverged_at = Some(*ix);
        }
    }
    Ok(ReplayReport {
        ops: ops.len(),
        diverged_at,
    })
}

crates/svc/src/main.rs.Text:
use std::{env, path::PathBuf, process::ExitCode};

use clap::{Args, Parser, Subcommand};
use serde::Serialize;
use serde_json::{Value, json};
use svc_core::engine::{
    add_def_at, classify_def, delete, diff as diff_snapshots, edit_def, extract_hoist, inline,
    move_def, relocate, rename, render_entity, resolve_add_def_file, show,
};
use svc_core::{EntityId, Intent, Op, OpIx, RelPath, Snapshot, SnapshotId};
use svc_repo::{
    Repo, Take, blame, branch, changeset_begin, changeset_end, changeset_status,
    changesets, checkout, conflicts as list_conflicts, describe, edit, evolog, heads, log,
    merge as merge_repo, new, op_log, op_restore, replay, resolve as resolve_conflict,
    resolve_entity, resolve_entity_in, status, undo, untracked_mentions, workspace,
};

mod agent;

#[derive(Parser)]
#[command(name = "svc", about = "Compiler-grade version control")]
struct Cli {
    #[arg(long, global = true)] json: bool,
    #[command(subcommand)] command: Command,
}

#[derive(Subcommand)]
enum Command {
    Init, Status, Describe { message: String }, New, Branch { name: String }, Edit { change: String }, Heads, Log,
    Evolog { change: String }, Show { entity: String }, ListDefs, ShowDef(ShowDefArgs),
    Search { query: String }, Diff { a: String, b: String }, Blame(EntityArg),
    Merge { change: String }, Conflicts,
    Resolve { conflict: usize, #[arg(long, help = "a = current change, b = merged-in, or base")] take: String },
    Undo,
    #[command(subcommand)] Op(OpCommand),
    #[command(subcommand)] Changeset(ChangeSetCommand),
    /// The local forge (crates/svc-forge): `export` writes its catalog from this store.
    #[command(subcommand)] Forge(ForgeCommand),
    #[command(subcommand)] History(HistoryCommand),
    #[command(subcommand)] Workspace(WorkspaceCommand),
    Checkout { snapshot: String }, Render, Replay, Rename(RenameArgs), Move(MoveArgs),
    Relocate(RelocateArgs), Extract(ExtractArgs), Inline(EntityArg), AddDef(AddDefArgs),
    Delete(DeleteArgs), EditDef(EditDefArgs), Classify(ClassifyArgs), Agent { task: String },
    /// Open the review UI; with `--agent <task>`, run that task under dsh inside it (demo line 12).
    Tui { #[arg(long)] agent: Option<String>, #[arg(long)] wire_log: bool },
}

#[derive(Subcommand)] enum OpCommand { Log, Restore { index: u64 } }
#[derive(Subcommand)] enum ForgeCommand { Export { #[arg(long)] out: Option<std::path::PathBuf> } }
#[derive(Subcommand)]
enum HistoryCommand {
    /// The op log from --since (default 1: everything after init) as a bundle, to stdout or --out.
    Export { #[arg(long, default_value_t = 1)] since: u64, #[arg(long)] out: Option<PathBuf> },
    /// Replay a bundle into this store; the tree must be the bundle's base.
    Import { file: PathBuf },
}
#[derive(Subcommand)]
enum WorkspaceCommand {
    Add { name: String, path: PathBuf, #[arg(long)] at: Option<String> },
    List,
    Forget { name: String },
    UpdateStale,
}
#[derive(Subcommand)]
enum ChangeSetCommand {
    Begin { name: String, #[arg(long, default_value = "refactor")] intent: String, #[arg(long)] force: bool },
    End,
    Status,
    List,
}
#[derive(Args)] struct EntityArg { #[arg(long)] entity: String }
#[derive(Args)] struct ShowDefArgs { #[arg(long)] entity: String, #[arg(long)] at: Option<String> }
#[derive(Args)] struct RenameArgs { #[arg(long)] entity: String, #[arg(long)] new_name: String }
#[derive(Args)] struct MoveArgs { #[arg(long)] entity: String, #[arg(long)] new_parent: String, #[arg(long)] ordinal: Option<u32> }
#[derive(Args)] struct RelocateArgs { #[arg(long)] entity: String, #[arg(long)] file: String, #[arg(long)] ordinal: u32 }
#[derive(Args)] struct ExtractArgs { #[arg(long)] entity: String, #[arg(long)] new_parent: Option<String> }
#[derive(Args)] struct AddDefArgs { #[arg(long)] id: Option<String>, #[arg(long)] parent: Option<String>, #[arg(long)] file: Option<String>, #[arg(long)] ordinal: u32, #[arg(long)] definition: String, #[arg(long)] intent: String }
#[derive(Args)] struct DeleteArgs { #[arg(long)] entity: String, #[arg(long)] intent: String }
#[derive(Args)] struct EditDefArgs { #[arg(long)] entity: String, #[arg(long)] definition: String, #[arg(long)] intent: String }
#[derive(Args)] struct ClassifyArgs { #[arg(long)] entity: String, #[arg(long)] definition: String }

fn main() -> ExitCode {
    // `svc list-defs --json | head` must not panic with "failed printing to stdout: Broken
    // pipe": restore SIGPIPE's default so a closed pipe ends the process quietly, as it
    // does for every other CLI tool.
    #[cfg(unix)]
    {
        unsafe extern "C" {
            fn signal(signum: i32, handler: usize) -> usize;
        }
        unsafe { signal(13 /* SIGPIPE */, 0 /* SIG_DFL */) };
    }
    let cli = Cli::parse();
    if let Command::Tui { agent: task, wire_log } = &cli.command {
        let cwd = match env::current_dir().and_then(|path| path.canonicalize()) {
            Ok(cwd) => cwd,
            Err(error) => {
                eprintln!("svc: could not resolve repository root: {error}");
                return ExitCode::FAILURE;
            }
        };
        let root = Repo::find_root(&cwd).unwrap_or(cwd);
        let svc_bin = match env::current_exe() {
            Ok(path) => path,
            Err(error) => {
                eprintln!("svc: could not locate its executable: {error}");
                return ExitCode::FAILURE;
            }
        };
        // Same launch as `svc agent`: pinned dsh, runtime overlay, SVC_BIN; the TUI opens
        // and closes the run's changeset itself and answers asks from its queue.
        // SVC_AGENT_COMMAND="node demo/replay-agent.mjs <recording>" hosts a scripted ACP
        // agent instead, for rehearsing line 12 without a model key.
        let agent = match task {
            None => None,
            Some(task) => match env::var("SVC_AGENT_COMMAND") {
                Ok(command) => {
                    let mut words = command.split_whitespace().map(str::to_string);
                    let Some(program) = words.next() else {
                        eprintln!("svc: SVC_AGENT_COMMAND is empty");
                        return ExitCode::FAILURE;
                    };
                    let mut config = svc_agent::AgentConfig::command(program, words.collect(), &root);
                    config.env.insert("SVC_BIN".into(), svc_bin.display().to_string());
                    Some((config, task.clone()))
                }
                Err(_) => {
                    if !agent::has_model_credentials() {
                        eprintln!("svc: no model credential found; set OPENROUTER_API_KEY, DEEPSEEK_API_KEY, ANTHROPIC_API_KEY, OPENAI_API_KEY, or XAI_API_KEY");
                        return ExitCode::FAILURE;
                    }
                    match agent::runtime_overlay(&root) {
                        Ok(overlay) => Some((svc_agent::AgentConfig::dsh(&root, &overlay, &svc_bin), task.clone())),
                        Err(error) => {
                            eprintln!("svc: {error}");
                            return ExitCode::FAILURE;
                        }
                    }
                }
            },
        };
        return match svc_tui::run(svc_tui::TuiOptions {
            svc_bin,
            root,
            agent,
            wire_log: *wire_log,
        }) {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => {
                eprintln!("svc: {error}");
                ExitCode::FAILURE
            }
        };
    }
    if let Command::Agent { task } = &cli.command {
        let runtime = match tokio::runtime::Runtime::new() {
            Ok(runtime) => runtime,
            Err(error) => {
                eprintln!("svc: could not start async runtime: {error}");
                return ExitCode::FAILURE;
            }
        };
        return match runtime.block_on(agent::run(task)) {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => {
                eprintln!("svc: {error}");
                ExitCode::FAILURE
            }
        };
    }
    if !cli.json {
        if let Some(result) = run_text(&cli) {
            return match result {
                Ok(text) => { println!("{text}"); ExitCode::SUCCESS }
                Err(error) => { eprintln!("svc: {error}"); ExitCode::FAILURE }
            };
        }
    }
    match run(&cli) {
        Ok(value) => { println!("{}", if cli.json { value.to_string() } else { serde_json::to_string_pretty(&value).unwrap() }); ExitCode::SUCCESS }
        Err(error) => { if cli.json { eprintln!("{}", json!({"error": error})) } else { eprintln!("svc: {error}") }; ExitCode::FAILURE }
    }
}

/// The sentence form of the verbs whose output people read at the expo (design §8: `--json`
/// is the machine form). `None` for every other verb, which then takes the JSON path.
fn run_text(cli: &Cli) -> Option<Result<String, String>> {
    use svc_repo::text;
    // `init` has to run before discover: there is no store yet.
    if matches!(cli.command, Command::Init) {
        return Some(init_text());
    }
    let cwd = env::current_dir().ok()?;
    let repo = Repo::discover(&cwd, Repo::default_langs()).ok()?;
    let snap = repo.current().ok()?;
    let out = match &cli.command {
        Command::Status => status(&repo).and_then(|s| repo.current().map(|snap| text::status(&snap, &s))),
        Command::Log => log(&repo, None).map(|l| text::log(&snap, &l)),
        Command::Op(OpCommand::Log) => op_log(&repo).map(|l| text::log(&snap, &l)),
        Command::Forge(ForgeCommand::Export { out }) => svc_repo::forge::export(&repo, out.as_deref())
            .map(|p| format!("wrote {} — serve it with: cargo run -p svc-forge -- --catalog {}", p.display(), p.display())),
        Command::History(HistoryCommand::Export { since, out }) => {
            return Some((|| {
                let b = svc_repo::bundle::export(&repo, OpIx(*since)).map_err(|e| e.to_string())?;
                match out {
                    Some(p) => {
                        let text = serde_json::to_string_pretty(&b).map_err(|e| e.to_string())?;
                        std::fs::write(p, text).map_err(|e| e.to_string())?;
                        Ok(format!("wrote {}: {} ops", p.display(), b.entries.len()))
                    }
                    None => serde_json::to_string_pretty(&b).map_err(|e| e.to_string()),
                }
            })());
        }
        Command::History(HistoryCommand::Import { file }) => {
            return Some((|| {
                let text = std::fs::read_to_string(file).map_err(|e| e.to_string())?;
                let b: svc_repo::bundle::Bundle = serde_json::from_str(&text).map_err(|e| e.to_string())?;
                let r = svc_repo::bundle::import(&repo, &b).map_err(|e| e.to_string())?;
                Ok(match r.diverged_at {
                    Some(at) => format!("replayed {} ops: diverged at #{}", r.applied, at.0),
                    None => format!("replayed {} ops: clean", r.applied),
                })
            })());
        }
        Command::Heads => heads(&repo).map(|h| text::heads(&h)),
        Command::Evolog { change } => repo
            .resolve_change(change)
            .and_then(|id| evolog(&repo, id))
            .map(|e| text::evolog(&e)),
        Command::Blame(arg) => resolve_entity(&repo, &arg.entity)
            .and_then(|id| blame(&repo, id))
            .map(|b| text::blame(&snap, &b)),
        Command::Conflicts => list_conflicts(&repo).map(|c| text::conflicts_named(&snap, repo.store(), repo.root_dir(), &c)),
        Command::Replay => replay(&repo).and_then(|r| {
            if r.ok() {
                Ok(format!("replayed {} operations: clean", r.ops))
            } else {
                Err(svc_core::Error::Other(format!(
                    "replay diverged at {:?}",
                    r.diverged_at
                )))
            }
        }),
        Command::Workspace(WorkspaceCommand::List) => {
            return Some(
                workspace::list(&repo)
                    .map(|rows| {
                        rows.iter()
                            .map(|row| {
                                let mark = if row.current { "@" } else { " " };
                                let change = row
                                    .change
                                    .as_ref()
                                    .map(|id| format!("  change⟨{}⟩", id.short()))
                                    .unwrap_or_default();
                                format!("{mark} {:<8} {}{change}", row.name, row.path.display())
                            })
                            .collect::<Vec<_>>()
                            .join("\n")
                    })
                    .map_err(|e| e.to_string()),
            );
        }
        Command::Merge { change } => merge_repo(&repo, change)
            .and_then(|m| repo.current().map(|s| text::merge(&s, repo.store(), repo.root_dir(), &m))),
        Command::Show { entity } => {
            // demo line 3: the canonical stream — `$n` local slots, `#name⟨hash⟩` refs.
            return Some(show_canonical(&repo, entity).map(|v| {
                format!("{entity}⟨{}⟩\n{}", v["short"].as_str().unwrap_or(""), v["canonical"].as_str().unwrap_or(""))
            }));
        }
        Command::New
        | Command::Branch { .. }
        | Command::Describe { .. }
        | Command::Undo
        | Command::Move(_)
        | Command::Relocate(_)
        | Command::Extract(_)
        | Command::Inline(_)
        | Command::AddDef(_)
        | Command::Delete(_)
        | Command::EditDef(_) => {
            return Some(run_with(cli, &repo).and_then(|v| text_of_this_op(&repo, &v)));
        }
        Command::Rename(args) => {
            return Some(rename_cmd(&repo, args).map(|v| {
                let from = v["renamed"]["from"].as_str().unwrap_or("?").to_string();
                let calls = v["untracked_mentions"]["method_calls"].as_u64().unwrap_or(0);
                let other = v["untracked_mentions"]["other"].as_u64().unwrap_or(0);
                let plural = |n: u64, s: &str| if n == 1 { s.to_string() } else { format!("{s}s") };
                let mut line = format!("renamed {from} → {}", args.new_name);
                if calls > 0 {
                    line.push_str(&format!(
                        "\n{calls} method {} `.{from}(…)` left unchanged: receiver types are not resolved",
                        plural(calls, "call")
                    ));
                }
                if other > 0 {
                    line.push_str(&format!(
                        "\n{other} other {} of `{from}` left unchanged (strings, comments, unrelated bindings)",
                        plural(other, "mention")
                    ));
                }
                line
            }));
        }
        Command::ListDefs => {
            let mut rows: Vec<_> = snap
                .entities
                .iter()
                .map(|(id, e)| (e.file.clone(), e.ordinal, e.kind, e.name.clone(), *id))
                .collect();
            rows.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)).then(a.3.cmp(&b.3)));
            let body = rows
                .into_iter()
                .map(|(file, _, kind, name, id)| format!("{kind:?} {name}  {file}  ⟨{}⟩", id.short()))
                .collect::<Vec<_>>()
                .join("\n");
            return Some(Ok(if body.is_empty() { "no definitions".into() } else { body }));
        }
        Command::ShowDef(arg) => return Some(show_def_text(&repo, &arg.entity, arg.at.as_deref())),
        Command::Search { query } => {
            return Some(search(&repo, query).map(|v| {
                let matches = v["matches"].as_array().cloned().unwrap_or_default();
                if matches.is_empty() {
                    format!("no matches for {query:?}")
                } else {
                    matches
                        .iter()
                        .map(|m| {
                            format!(
                                "{} {}  {}",
                                m["kind"].as_str().unwrap_or("?"),
                                m["name"].as_str().unwrap_or("?"),
                                m["file"].as_str().unwrap_or("")
                            )
                        })
                        .collect::<Vec<_>>()
                        .join("\n")
                }
            }));
        }
        Command::Classify(args) => {
            return Some(classify_cmd(&repo, args).map(|v| {
                format!(
                    "{} would be {} (not committed)",
                    args.entity,
                    v["observed"].as_str().unwrap_or("?")
                )
            }));
        }
        Command::Workspace(WorkspaceCommand::Add { name, path, .. }) => {
            return Some(run_with(cli, &repo).map(|v| {
                let shown = v["path"].as_str().map(str::to_string).unwrap_or_else(|| path.display().to_string());
                format!("added workspace {name} at {shown}")
            }));
        }
        Command::Workspace(WorkspaceCommand::Forget { name }) => {
            return Some(run_with(cli, &repo).map(|_| format!("forgot workspace {name}")));
        }
        Command::Workspace(WorkspaceCommand::UpdateStale) => {
            return Some(run_with(cli, &repo).map(|v| {
                format!("workspace {} is current", v["name"].as_str().unwrap_or("default"))
            }));
        }
        Command::Edit { change } => {
            return Some(edit(&repo, change).map(|_| format!("now editing {change}")).map_err(|e| e.to_string()));
        }
        Command::Checkout { snapshot } => {
            return Some((|| {
                let id = snapshot.parse::<SnapshotId>().map_err(|e| e.to_string())?;
                checkout(&repo, id).map_err(|e| e.to_string())?;
                Ok(format!("checked out {snapshot}"))
            })());
        }
        Command::Render => {
            return Some(run_with(cli, &repo).map(|_| "rendered working copy".into()));
        }
        Command::Resolve { conflict, take } => {
            return Some(run_with(cli, &repo).map(|_| format!("took {take} on conflict {conflict}")));
        }
        Command::Op(OpCommand::Restore { index }) => {
            return Some(run_with(cli, &repo).and_then(|v| {
                text_of_this_op(&repo, &v).map(|s| {
                    if s.is_empty() {
                        format!("restored op {index}")
                    } else {
                        s
                    }
                })
            }));
        }
        Command::Diff { a, b } => {
            return Some((|| {
                let left = resolve_snapshot(&repo, a)?;
                let right = resolve_snapshot(&repo, b)?;
                let deltas = diff_snapshots(repo.store(), &left, &right).map_err(|e| e.to_string())?;
                if deltas.is_empty() {
                    Ok("no differences".into())
                } else {
                    Ok(deltas.iter().map(|d| text::delta(&right, d)).collect::<Vec<_>>().join("\n"))
                }
            })());
        }
        Command::Changeset(ChangeSetCommand::Begin { name, .. }) => {
            return Some(run_with(cli, &repo).map(|_| format!("changeset {name} open")));
        }
        Command::Changeset(ChangeSetCommand::End) => {
            return Some(run_with(cli, &repo).map(|v| {
                if v.is_null() {
                    "no open changeset".into()
                } else {
                    format!("closed changeset {}", v.as_str().unwrap_or("?"))
                }
            }));
        }
        Command::Changeset(ChangeSetCommand::Status) => {
            return Some(run_with(cli, &repo).map(|v| {
                if v.is_null() {
                    "no open changeset".into()
                } else {
                    format!(
                        "open changeset {} ({} ops)",
                        v["name"].as_str().unwrap_or("?"),
                        v["ops"].as_array().map(|a| a.len()).unwrap_or(0)
                    )
                }
            }));
        }
        Command::Changeset(ChangeSetCommand::List) => {
            return Some(
                changesets(&repo)
                    .map(|rows| {
                        if rows.is_empty() {
                            "no changesets".into()
                        } else {
                            rows.iter()
                                .map(|c| {
                                    let mark = if c.open { "*" } else { " " };
                                    format!("{mark} {} ({:?}, {} ops)", c.name, c.intent, c.ops.len())
                                })
                                .collect::<Vec<_>>()
                                .join("\n")
                        }
                    })
                    .map_err(|e| e.to_string()),
            );
        }
        _ => return None,
    };
    Some(out.map_err(|e| e.to_string()))
}

fn run(cli: &Cli) -> Result<Value, String> {
    if matches!(cli.command, Command::Init) {
        let cwd = env::current_dir().map_err(|e| e.to_string())?;
        let repo = Repo::init(&cwd, Repo::default_langs()).map_err(|e| e.to_string())?;
        return Ok(json!({"root": repo.root_dir(), "change": repo.current_change().map_err(|e| e.to_string())?}));
    }
    let cwd = env::current_dir().map_err(|e| e.to_string())?;
    let repo = Repo::discover(&cwd, Repo::default_langs()).map_err(|e| e.to_string())?;
    run_with(cli, &repo)
}

/// The verb dispatch over an already-open repository (redb admits one opener per process).
fn run_with(cli: &Cli, repo: &Repo) -> Result<Value, String> {
    let repo = repo;
    match &cli.command {
        Command::Status => value(status(&repo)),
        Command::Describe { message } => value(describe(&repo, message)),
        Command::New => value(new(&repo)),
        Command::Branch { name } => value(branch(&repo, name)),
        Command::Edit { change } => value(edit(&repo, change)),
        Command::Heads => value(heads(&repo)),
        Command::Log => value(log(&repo, None)),
        Command::Evolog { change } => { let id = repo.resolve_change(change).map_err(|e| e.to_string())?; value(evolog(&repo, id)) }
        Command::Blame(arg) => value(blame(&repo, resolve_entity(&repo, &arg.entity).map_err(|e| e.to_string())?)),
        Command::Undo => value(undo(&repo)),
        Command::Merge { change } => value(merge_repo(&repo, change)),
        Command::Conflicts => value(list_conflicts(&repo)),
        Command::Resolve { conflict, take } => {
            value(resolve_conflict(&repo, *conflict, parse_take(take)?))
        }
        Command::Op(OpCommand::Log) => value(op_log(&repo)),
        Command::Op(OpCommand::Restore { index }) => value(op_restore(&repo, OpIx(*index))),
        Command::Changeset(ChangeSetCommand::Begin { name, intent, force }) => {
            value(changeset_begin(&repo, name, parse_intent(intent), None, *force))
        }
        Command::Changeset(ChangeSetCommand::End) => value(changeset_end(&repo)),
        Command::Forge(ForgeCommand::Export { out }) => svc_repo::forge::export(&repo, out.as_deref()).map(|p| json!({"path": p})).map_err(|e| e.to_string()),
        Command::History(HistoryCommand::Export { since, out }) => {
            let b = svc_repo::bundle::export(repo, OpIx(*since)).map_err(|e| e.to_string())?;
            match out {
                Some(p) => {
                    let text = serde_json::to_string_pretty(&b).map_err(|e| e.to_string())?;
                    std::fs::write(p, &text).map_err(|e| e.to_string())?;
                    Ok(json!({"path": p, "ops": b.entries.len()}))
                }
                None => serde_json::to_value(&b).map_err(|e| e.to_string()),
            }
        }
        Command::History(HistoryCommand::Import { file }) => {
            let text = std::fs::read_to_string(file).map_err(|e| e.to_string())?;
            let b: svc_repo::bundle::Bundle = serde_json::from_str(&text).map_err(|e| e.to_string())?;
            let r = svc_repo::bundle::import(repo, &b).map_err(|e| e.to_string())?;
            serde_json::to_value(&r).map_err(|e| e.to_string())
        }
        Command::Changeset(ChangeSetCommand::Status) => value(changeset_status(&repo)),
        Command::Changeset(ChangeSetCommand::List) => value(changesets(&repo)),
        Command::Workspace(WorkspaceCommand::Add { name, path, at }) => {
            let change = at
                .as_deref()
                .map(|value| repo.resolve_change(value).map_err(|e| e.to_string()))
                .transpose()?;
            value(workspace::add(&repo, name, path, change))
        }
        Command::Workspace(WorkspaceCommand::List) => value(workspace::list(&repo)),
        Command::Workspace(WorkspaceCommand::Forget { name }) => {
            value(workspace::forget(&repo, name))
        }
        Command::Workspace(WorkspaceCommand::UpdateStale) => value(workspace::update_stale(&repo)),
        Command::Replay => {
            let report = replay(&repo).map_err(|e| e.to_string())?;
            if !report.ok() {
                return Err(format!("replay diverged at {:?}", report.diverged_at));
            }
            value(Ok(report))
        }
        Command::Checkout { snapshot } => {
            let id = snapshot.parse::<SnapshotId>().map_err(|e| e.to_string())?;
            value(checkout(&repo, id))
        }
        Command::Render => { let snapshot = repo.current().map_err(|e| e.to_string())?; repo.render_to_disk(&snapshot).map_err(|e| e.to_string())?; Ok(json!({"rendered": true})) }
        Command::ListDefs => list_defs(&repo),
        Command::ShowDef(arg) => show_def(&repo, &arg.entity, arg.at.as_deref()),
        Command::Show { entity } => show_canonical(&repo, entity),
        Command::Search { query } => search(&repo, query),
        Command::Diff { a, b } => diff(&repo, a, b),
        Command::Rename(args) => rename_cmd(&repo, args),
        Command::Move(args) => move_cmd(&repo, args),
        Command::Relocate(args) => relocate_cmd(&repo, args),
        Command::Extract(args) => extract_cmd(&repo, args),
        Command::Inline(arg) => inline_cmd(&repo, &arg.entity),
        Command::AddDef(args) => add_def_cmd(&repo, args),
        Command::Delete(args) => delete_cmd(&repo, args),
        Command::EditDef(args) => edit_def_cmd(&repo, args),
        Command::Classify(args) => classify_cmd(&repo, args),
        Command::Tui { .. } => unreachable!("handled before the repository opens"),
        command => Err(format!("{} is not wired to the engine yet", command_name(command))),
    }
}

fn value<T: Serialize>(result: svc_core::Result<T>) -> Result<Value, String> {
    serde_json::to_value(result.map_err(|e| e.to_string())?).map_err(|e| e.to_string())
}

fn parse_intent(value: &str) -> Intent {
    match value {
        "refactor" => Intent::Refactor,
        "fix" => Intent::Fix,
        "feature" => Intent::Feature,
        "docs" => Intent::Docs,
        other => Intent::Other(other.to_owned()),
    }
}

fn parse_take(value: &str) -> Result<Take, String> {
    match value {
        "a" => Ok(Take::A),
        "b" => Ok(Take::B),
        "base" => Ok(Take::Base),
        _ => Err("--take: a = current change, b = merged-in, or base".into()),
    }
}

fn definition_bytes(definition: &str) -> Vec<u8> {
    let mut bytes = definition.as_bytes().to_vec();
    if !bytes.ends_with(b"\n") {
        bytes.push(b'\n');
    }
    bytes
}

fn init_text() -> Result<String, String> {
    let cwd = env::current_dir().map_err(|e| e.to_string())?;
    let repo = Repo::init(&cwd, Repo::default_langs()).map_err(|e| e.to_string())?;
    let n = repo.current().map(|s| s.entities.len()).map_err(|e| e.to_string())?;
    Ok(format!("initialized {} — {n} entities", repo.root_dir().display()))
}

fn show_def_text(repo: &Repo, query: &str, at: Option<&str>) -> Result<String, String> {
    show_def(repo, query, at).map(|v| {
        v["text"].as_str().map(str::to_string).unwrap_or_else(|| serde_json::to_string_pretty(&v).unwrap_or_default())
    })
}

fn list_defs(repo: &Repo) -> Result<Value, String> {
    let snapshot = repo.current().map_err(|e| e.to_string())?;
    Ok(json!({"definitions": snapshot.entities.into_iter().map(|(id, entity)| json!({
        "id": id, "name": entity.name, "kind": entity.kind, "file": entity.file,
        "parent": entity.parent, "ordinal": entity.ordinal
    })).collect::<Vec<_>>() }))
}

fn show_def(repo: &Repo, query: &str, at: Option<&str>) -> Result<Value, String> {
    let snap = match at {
        Some(spec) => resolve_snapshot(repo, spec)?,
        None => repo.current().map_err(|e| e.to_string())?,
    };
    let id = resolve_entity_in(&snap, query).map_err(|e| e.to_string())?;
    let canonical = show(repo.store(), &snap, id).map_err(|e| e.to_string())?;
    let entity = snap.entities.get(&id).cloned().ok_or_else(|| format!("missing {query}"))?;
    let bytes = repo.store().get_bytes_blob(entity.bytes).map_err(|e| e.to_string())?;
    let content = repo.store().get_content(entity.content).map_err(|e| e.to_string())?;
    let (src, _) = render_entity(&snap, repo.store(), id, false).map_err(|e| e.to_string())?;
    let text = String::from_utf8_lossy(&src);
    Ok(json!({"id": id, "entity": entity, "canonical": canonical, "bytes": bytes, "content": content, "text": text}))
}

fn show_canonical(repo: &Repo, query: &str) -> Result<Value, String> {
    let id = resolve_entity(repo, query).map_err(|e| e.to_string())?;
    let snapshot = repo.current().map_err(|e| e.to_string())?;
    let canonical = show(repo.store(), &snapshot, id).map_err(|e| e.to_string())?;
    Ok(json!({"id": id, "short": id.short(), "canonical": canonical}))
}

fn mutation_value(m: svc_repo::Mutation) -> Result<Value, String> {
    Ok(json!({
        "op": m.ix,
        "snapshot": m.snapshot,
        "observed": m.entry.observed,
        "flagged": m.entry.flagged(),
        "closed_stale_changeset": m.closed_stale_changeset,
    }))
}

/// The sentence for *this* verb's op (`m.ix` / MutationOut.ix), not `op_log().first()`
/// (newest in the shared journal — wrong when two checkouts publish at once).
fn text_of_this_op(repo: &Repo, v: &Value) -> Result<String, String> {
    use svc_repo::text;
    let snap = repo.current().map_err(|e| e.to_string())?;
    let entries = op_log(repo).map_err(|e| e.to_string())?;
    let want = v["op"].as_u64().or_else(|| v["ix"].as_u64());
    let entry = want
        .and_then(|n| entries.iter().find(|e| e.ix.0 == n))
        .or_else(|| entries.first());
    Ok(entry.map(|e| text::op(&snap, e)).unwrap_or_default())
}

fn search(repo: &Repo, query: &str) -> Result<Value, String> {
    let needle = query.to_ascii_lowercase();
    let snapshot = repo.current().map_err(|e| e.to_string())?;
    let matches = snapshot
        .entities
        .iter()
        .filter(|(id, entity)| {
            id.to_string().to_ascii_lowercase().contains(&needle)
                || entity.name.to_ascii_lowercase().contains(&needle)
                || entity.file.as_str().to_ascii_lowercase().contains(&needle)
                || format!("{:?}", entity.kind).to_ascii_lowercase().contains(&needle)
                || render_entity(&snapshot, repo.store(), **id, false)
                    .ok()
                    .is_some_and(|(src, _)| {
                        String::from_utf8_lossy(&src).to_ascii_lowercase().contains(&needle)
                    })
        })
        .map(|(id, entity)| json!({
            "id": id, "name": entity.name, "kind": entity.kind, "file": entity.file,
            "parent": entity.parent, "ordinal": entity.ordinal,
        }))
        .collect::<Vec<_>>();
    Ok(json!({"matches": matches}))
}

fn resolve_snapshot(repo: &Repo, spec: &str) -> Result<Snapshot, String> {
    if let Ok(id) = spec.parse::<SnapshotId>() {
        if let Ok(snapshot) = repo.store().get_snapshot(id) {
            return Ok(snapshot);
        }
    }
    let change = repo.resolve_change(spec).map_err(|e| e.to_string())?;
    let id = repo
        .store()
        .head(change)
        .map_err(|e| e.to_string())?;
    repo.store().get_snapshot(id).map_err(|e| e.to_string())
}

fn diff(repo: &Repo, a: &str, b: &str) -> Result<Value, String> {
    let a = resolve_snapshot(repo, a)?;
    let b = resolve_snapshot(repo, b)?;
    Ok(json!({"deltas": diff_snapshots(repo.store(), &a, &b).map_err(|e| e.to_string())?}))
}

fn resolve_parent(repo: &Repo, parent: &str) -> Result<Option<EntityId>, String> {
    match parent {
        "root" | "none" | "-" => Ok(None),
        value => resolve_entity(repo, value).map(Some).map_err(|e| e.to_string()),
    }
}

fn rename_cmd(repo: &Repo, args: &RenameArgs) -> Result<Value, String> {
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let old = repo.current().ok().and_then(|s| s.entities.get(&id).map(|r| r.name.clone()));
    let op = Op::Rename { id, new: args.new_name.clone() };
    let m = repo
        .mutate(op, None, |repo, cur| repo.amend(cur, rename(cur, id, &args.new_name)?))
        .map_err(|e| e.to_string())?;
    // Mentions of the old name svc did not resolve (method calls on typed receivers,
    // strings, comments) are left as they were; say how many rather than hide it.
    let untracked = match &old {
        Some(old) if old != &args.new_name => untracked_mentions(repo, old).unwrap_or_default(),
        _ => Default::default(),
    };
    let mut v = mutation_value(m)?;
    v["renamed"] = json!({ "from": old, "to": args.new_name });
    v["untracked_mentions"] = json!(untracked);
    Ok(v)
}

fn move_cmd(repo: &Repo, args: &MoveArgs) -> Result<Value, String> {
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let parent = resolve_parent(repo, &args.new_parent)?;
    let op = Op::Move { id, parent, ordinal: args.ordinal };
    let m = repo
        .mutate(op, None, |repo, cur| repo.amend(cur, move_def(repo.store(), repo.langs(), cur, id, parent, args.ordinal)?))
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn relocate_cmd(repo: &Repo, args: &RelocateArgs) -> Result<Value, String> {
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let file = RelPath::new(args.file.clone()).map_err(|p| format!("invalid --file {p}"))?;
    let op = Op::Relocate { id, file: file.clone(), ordinal: args.ordinal };
    let m = repo
        .mutate(op, None, |repo, cur| repo.amend(cur, relocate(cur, repo.store(), id, file, args.ordinal)?))
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn extract_cmd(repo: &Repo, args: &ExtractArgs) -> Result<Value, String> {
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let parent = args
        .new_parent
        .as_deref()
        .map(|p| resolve_parent(repo, p))
        .transpose()?
        .flatten();
    let ordinal = repo
        .current()
        .map_err(|e| e.to_string())?
        .entities
        .get(&id)
        .map(|e| e.ordinal)
        .ok_or_else(|| format!("no such entity: {}", args.entity))?;
    let op = Op::Extract { id, new_parent: parent, ordinal };
    let m = repo
        .mutate(op, None, |repo, cur| repo.amend(cur, extract_hoist(repo.store(), repo.langs(), cur, id, parent, ordinal)?))
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn inline_cmd(repo: &Repo, entity: &str) -> Result<Value, String> {
    let id = resolve_entity(repo, entity).map_err(|e| e.to_string())?;
    let m = repo
        .mutate(Op::Inline { id }, None, |repo, cur| {
            repo.amend(cur, inline(repo.store(), repo.langs(), cur, id)?)
        })
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn add_def_cmd(repo: &Repo, args: &AddDefArgs) -> Result<Value, String> {
    let id: EntityId = match &args.id {
        Some(id) => serde_json::from_value(Value::String(id.clone()))
            .map_err(|e| format!("invalid entity id: {e}"))?,
        None => EntityId::new(),
    };
    let parent = args
        .parent
        .as_deref()
        .map(|p| resolve_parent(repo, p))
        .transpose()?
        .flatten();
    let intent = parse_intent(&args.intent);
    let definition = definition_bytes(&args.definition);
    let file = match args.file.as_deref() {
        Some(s) => Some(RelPath::new(s).map_err(|p| format!("invalid --file {p}"))?),
        None => None,
    };
    let current = repo.current().map_err(|e| e.to_string())?;
    let file = resolve_add_def_file(&current, repo.langs(), parent, file)
        .map_err(|e| e.to_string())?;
    let op = Op::AddDef {
        id,
        parent,
        ordinal: args.ordinal,
        definition: args.definition.clone(),
        intent: intent.clone(),
        file: Some(file.clone()),
    };
    let m = repo
        .mutate(op, None, |repo, cur| {
            let next = add_def_at(
                repo.store(), repo.langs(), cur, id, parent, Some(file.clone()),
                args.ordinal, &definition, intent,
            )?;
            repo.amend(cur, next)
        })
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn delete_cmd(repo: &Repo, args: &DeleteArgs) -> Result<Value, String> {
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let intent = parse_intent(&args.intent);
    let op = Op::Delete { id, intent };
    let m = repo
        .mutate(op, None, |repo, cur| repo.amend(cur, delete(cur, repo.store(), id)?))
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn edit_def_cmd(repo: &Repo, args: &EditDefArgs) -> Result<Value, String> {
    repo.absorb().map_err(|e| e.to_string())?;
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let current = repo.current().map_err(|e| e.to_string())?;
    let definition = definition_bytes(&args.definition);
    let observed = classify_def(
        repo.store(), repo.langs(), &current, id, &definition,
    )
    .map_err(|e| e.to_string())?;
    let intent = parse_intent(&args.intent);
    let op = Op::EditDef {
        id,
        definition: args.definition.clone(),
        intent,
    };
    let m = repo
        .mutate(op, Some(observed), |repo, cur| {
            let (next, _) = edit_def(
                repo.store(), repo.langs(), cur, id, &definition,
            )?;
            repo.amend(cur, next)
        })
        .map_err(|e| e.to_string())?;
    mutation_value(m)
}

fn classify_cmd(repo: &Repo, args: &ClassifyArgs) -> Result<Value, String> {
    let id = resolve_entity(repo, &args.entity).map_err(|e| e.to_string())?;
    let current = repo.current().map_err(|e| e.to_string())?;
    let definition = definition_bytes(&args.definition);
    let observed = classify_def(
        repo.store(), repo.langs(), &current, id, &definition,
    )
    .map_err(|e| e.to_string())?;
    Ok(json!({"observed": observed, "committed": false}))
}

fn command_name(command: &Command) -> &'static str {
    match command {
        Command::Search { .. } => "search", Command::Diff { .. } => "diff",
        Command::Rename(_) => "rename", Command::Move(_) => "move", Command::Relocate(_) => "relocate",
        Command::Extract(_) => "extract", Command::Inline(_) => "inline", Command::AddDef(_) => "add-def",
        Command::Delete(_) => "delete", Command::EditDef(_) => "edit-def", Command::Classify(_) => "classify",
        Command::Agent { .. } => "agent", Command::Tui { .. } => "tui", Command::Workspace(_) => "workspace", Command::History(_) => "history", Command::Replay => "replay", _ => unreachable!(),
    }
}

